def count_queens(n: int, blocked: list[tuple[int, int]]) -> int:
    # Convert blocked squares to a set for faster lookup
    blocked = set(blocked)

    def is_safe(row: int, col: int) -> bool:
        # Check if there is a queen in the same row or column
        for i in range(col):
            if board[row][i] == 1:
                return False

        # Check if there is a queen in the upper diagonal on left side
        for i, j in zip(range(row, -1, -1), range(col, -1, -1)):
            if board[i][j] == 1:
                return False

        # Check if there is a queen in the lower diagonal on left side
        for i, j in zip(range(row, n, 1), range(col, -1, -1)):
            if board[i][j] == 1:
                return False

        return True

    def solve_n_queens(col: int) -> int:
        # Base case: If all queens are placed, return 1
        if col >= n:
            return 1

        # Consider this column and try placing a queen in all rows one by one
        count = 0
        for i in range(n):
            if (i, col) not in blocked:
                board[i][col] = 1
                if is_safe(i, col):
                    count += solve_n_queens(col + 1)
                # If placing queen in board[i][col] doesn't lead to a solution,
                # then remove queen from board[i][col]
                board[i][col] = 0

        return count

    # Initialize board
    board = [[0]*n for _ in range(n)]

    # Place queens on blocked squares
    for i, j in blocked:
        board[i][j] = 1

    # Start placing queens from the first column
    return solve_n_queens(0)
