from collections import defaultdict

def count_shortest_paths(n: int, edges: list[tuple[int, int]], source: int, target: int) -> int:
    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)

    # Initialize distance from source to all other nodes as infinity
    distances = [float('inf')] * n
    distances[source] = 0

    # Relax all edges |V| - 1 times.
    for _ in range(n - 1):
        for u in range(n):
            for v in graph[u]:
                distances[v] = min(distances[v], distances[u] + 1)

    # If we can still relax, then there is a negative cycle
    for u in range(n):
        for v in graph[u]:
            if distances[v] > distances[u] + 1:
                return 0

    # Count the number of shortest paths from source to target
    count = 0
    for i in range(n):
        if distances[i] == distances[target]:
            count += 1

    return count
