        if node not in visited or cost < visited[node]:
            visited[node] = cost
            path = path + [node]
            if node == goal:
                return cost, path
            for (next_node, next_cost) in graph.get(node, []):
                if next_node not in visited or cost + next_cost < visited[next_node]:
                    visited[next_node] = cost + next_cost
                    heapq.heappush(queue, (cost + next_cost, next_node, path))
    return None
