def pascal_row(n: int) -> list[int]:
    if n == 0:
        return [1]
    else:
        row = [1]
        last_row = pascal_row(n-1)
        for i in range(len(last_row) - 1):
            row.append(last_row[i] + last_row[i+1])
        row.append(1)
        return row
