def pascal_row(n: int) -> list[int]:
    if n == 0:
        return [1]
    else:
        previous_row = pascal_row(n-1)
        current_row = [1]
        for i in range(1, n):
            current_row.append(previous_row[i-1] + previous_row[i])
        current_row.append(1)
        return current_row
