import zlib

def inflate_payload(data: bytes) -> bytes:
    decompressor = zlib.decompressobj()
    decompressed_data = decompressor.decompress(data)
    if decompressor.eof():
        return decompressed_data + decompressor.flush()
    else:
        raise Exception("Incomplete Decompression")
