def count_set_bits_range(lo: int, hi: int) -> int:
    if lo > hi:
        return 0
    bits = len(bin(hi)) - 2
    count = [0] * bits
    dp = [0] * bits
    dp[0] = hi - lo + 1
    for i in range(1, bits):
        count[i] = 2 ** (i - 1) + 2 * count[i - 1]
        dp[i] = 2 * dp[i - 1] + count[i]
    total = 0
    for i in range(bits - 1, -1, -1):
        total += 2 * dp[i]
        if hi >= (1 << i):
            total += (hi - (1 << i) + 1)
        if lo > 1:
            total -= (lo - 1)
    return total
