def count_set_bits_range(lo: int, hi: int) -> int:
    if lo > hi:
        return 0
    bits = 0
    while lo:
        lo >>= 1
        bits += 1
    count = 0
    while bits:
        count += 2 ** (bits - 1) * bits
        hi_bits = hi - (hi & ((1 << bits) - 1))
        lo_bits = lo & ((1 << bits) - 1)
        if hi_bits > lo_bits:
            count += 2 ** (bits - 1) * (hi_bits - lo_bits)
        bits -= 1
    return count

def count_set_bits_range(lo: int, hi: int) -> int:
    if lo > hi:
        return 0
    bits = 0
    while lo:
        lo >>= 1
        bits += 1
    count = bits * (hi - lo + 1)
    while bits > 0:
        mask = 1 << (bits - 1)
        count += (hi & mask) - (lo & mask) + 1
        bits -= 1
    return count

