def rolling_variance(nums: list[float], k: int) -> list[float]:
    if k <= 0 or k > len(nums):
        return []
    else:
        means = [sum(nums[:k])/k]
        squares_sums = [sum([(i - means[0])**2 for i in nums[:k]])]
        for i in range(k, len(nums)):
            new_mean = (means[-1]*k + nums[i])/(k+1)
            means.append(new_mean)
            squares_sums.append(squares_sums[-1] - (nums[i-k] - means[-2])**2 + (nums[i] - means[-1])**2)
        variances = [round(squares_sums[i]/k, 3) for i in range(k-1, len(nums))]
        return variances

def rolling_variance(nums: list[float], k: int) -> list[float]:
    if k <= 0 or k > len(nums):
        return []
    else:
        variances = []
        for i in range(k, len(nums)+1):
            window = nums[i-k:i]
            mean = sum(window) / k
            squares_sum = sum((x - mean) ** 2 for x in window)
            variance = squares_sum / k
            variances.append(round(variance, 3))
        return variances

def rolling_variance(nums: list[float], k: int) -> list[float]:
    if k <= 0 or k > len(nums):
        return []
    else:
        means = [sum(nums[:k])/k]
        squares = [sum((x - means[0])**2 for x in nums[:k])]
        for i in range(k, len(nums)):
            new_mean = (means[-1]*k + nums[i])/(k+1)
            new_square = squares[-1] + (nums[i] - means[-1])**2 + (nums[i-k] - new_mean)**2
            means.append(new_mean)
            squares.append(new_square)
        variances = [round(squares[i]/(k-1), 3) for i in range(k-1, len(squares))]
        return variances

