                visited[neighbor] = 1
                heapq.heappush(queue, (dist + 1, neighbor, path_count))
            elif visited[neighbor] and dist + 1 == visited[neighbor]:
                heapq.heappush(queue, (dist + 1, neighbor, path_count + visited[neighbor]))

    return count % (10**9 + 7) if count else (1 if source == target else 0)
