def matrix_power_mod(matrix: list[list[int]], exp: int, mod: int) -> list[list[int]]:
    def matrix_multiply_mod(a: list[list[int]], b: list[list[int]], mod: int) -> list[list[int]]:
        result = [[0 for _ in range(len(b[0]))] for _ in range(len(a))]
        for i in range(len(a)):
            for j in range(len(b[0])):
                for k in range(len(b)):
                    result[i][j] = (result[i][j] + a[i][k] * b[k][j]) % mod
        return result

    def matrix_power(matrix: list[list[int]], exp: int, mod: int) -> list[list[int]]:
        if exp == 0:
            return [[1 if i == j else 0 for j in range(len(matrix))] for i in range(len(matrix))]
        elif exp == 1:
            return matrix
        else:
            half = matrix_power(matrix, exp // 2, mod)
            if exp % 2 == 0:
                return matrix_multiply_mod(half, half, mod)
            else:
                return matrix_multiply_mod(matrix_multiply_mod(half, half, mod), matrix, mod)

    return matrix_power(matrix, exp, mod)
