def identifier_to_snake(name: str) -> str:
    if not name.isascii():
        raise ValueError("Name must be ASCII")
    if not name:
        raise ValueError("Name cannot be empty")
    if not name[0].islower():
        raise ValueError("Name must start with a lowercase letter")
