from collections import deque

def shortest_path_one_break(grid: list[str]) -> int:
    rows, cols = len(grid), len(grid[0])
    start, end = None, None
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 'S':
                start = (i, j)
            elif grid[i][j] == 'E':
                end = (i, j)
    if start is None or end is None:
        return -1

    queue = deque([(start, 0, False)])  # (position, steps, broken)
    visited = {start: (0, False)}  # (steps, broken)
    while queue:
        (x, y), steps, broken = queue.popleft()
        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nx, ny = x + dx, y + dy
            if 0 <= nx < rows and 0 <= ny < cols:
                if grid[nx][ny] == '#' and not broken:
                    new_broken = True
                else:
                    new_broken = broken
                new_pos = (nx, ny)
                if new_pos == end:
                    return steps + 1
                if new_pos not in visited or visited[new_pos][1] != new_broken:
                    visited[new_pos] = (steps + 1, new_broken)
                    queue.append((new_pos, steps + 1, new_broken))
    return -1
