from collections import deque

def shortest_path_one_break(grid: list[str]) -> int:
    rows, cols = len(grid), len(grid[0])
    start, end = (-1, -1), (-1, -1)
    breaks = []

    # Find start, end and break positions
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 'S':
                start = (i, j)
            elif grid[i][j] == 'E':
                end = (i, j)
            elif grid[i][j] == '#':
                breaks.append((i, j))

    # If start or end is not found, return -1
    if start == (-1, -1) or end == (-1, -1):
        return -1

    # Directions for moving up, down, left, right
    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]

    # BFS
    queue = deque([(start, 0)])
    visited = {start}
    while queue:
        (x, y), steps = queue.popleft()
        if (x, y) == end:
            return steps
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < rows and 0 <= ny < cols and grid[nx][ny] != '#' and (nx, ny) not in visited:
                visited.add((nx, ny))
                queue.append(((nx, ny), steps + 1))

        # Try breaking a wall
        for bx, by in breaks:
            if (bx, by) not in visited:
                visited.add((bx, by))
                queue.append(((bx, by), steps + 1))

    # If no path found, return -1
    return -1
```

