        result = [[0] * len(matrix) for _ in range(len(matrix))]
        for i in range(len(matrix)):
            result[i][i] = 1
        while exp > 0:
            if exp % 2 == 1:
                result = matrix_multiply_mod(result, matrix, mod)
            matrix = matrix_multiply_mod(matrix, matrix, mod)
            exp //= 2
        return result

