from collections import deque

def shortest_path_one_break(grid):
    rows, cols = len(grid), len(grid[0])
    start, end = (-1, -1), (-1, -1)
    walls = []
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 'S':
                start = (i, j)
            elif grid[i][j] == 'E':
                end = (i, j)
            elif grid[i][j] == '#':
                walls.append((i, j))

    if start == (-1, -1) or end == (-1, -1):
        return -1

    queue = deque([(*start, 0, 0)])  # (row, col, breaks, steps)
    visited = {start}
    while queue:
        r, c, b, s = queue.popleft()
        if (r, c) == end:
            return s

        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] != '#' and (nr, nc) not in visited:
                visited.add((nr, nc))
                queue.append((nr, nc, b, s + 1))

        if b < len(walls):
            wr, wc = walls[b]
            if (wr, wc) not in visited:
                visited.add((wr, wc))
                queue.append((wr, wc, b + 1, s + 1))

    return -1
