def count_shortest_paths(n: int, edges: list[tuple[int, int]], source: int, target: int) -> int:
    graph = [[] for _ in range(n)]
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    queue = [(0, source, 1)]
    visited = [0] * n
    paths = [0] * n
    paths[source] = 1

    while queue:
        dist, node, path_count = heapq.heappop(queue)
        if node == target:
            return path_count
        if visited[node]:
            continue
        visited[node] = 1
        for neighbor in graph[node]:
            if not visited[neighbor]:
                new_dist = dist + 1
                paths[neighbor] = (paths[neighbor] + path_count) % (10**9 + 7)
                heapq.heappush(queue, (new_dist, neighbor, paths[neighbor]))
    return 0

