def count_queens(n: int, blocked: list[tuple[int, int]]) -> int:
    if n == 0:
        return 1

    # Convert blocked squares to a set for faster lookup
    blocked_squares = set(blocked)

    # Function to check if a queen can be placed at position (row, col)
    def can_place(row, col):
        # Check if there is a queen in the same row or column
        for i in range(n):
            if (row, i) in blocked_squares or (i, col) in blocked_squares:
                return False
        # Check if there is a queen in the diagonal
        for i in range(n):
            if (row - i, col - i) in blocked_squares or (row - i, col + i) in blocked_squares or \
               (row + i, col - i) in blocked_squares or (row + i, col + i) in blocked_squares:
                return False
        return True

    # Function to place queens recursively
    def place_queens(row):
        if row == n:
            return 1
        count = 0
        for col in range(n):
            if can_place(row, col):
                blocked_squares.add((row, col))
                count += place_queens(row + 1)
                blocked_squares.remove((row, col))
        return count

    return place_queens(0)
