def lex_topological_order(n: int, pairs: list[tuple[int, int]]) -> list[int]:
    # Create adjacency list
    adj_list = {i: [] for i in range(n)}
    for a, b in pairs:
        adj_list[a].append(b)

    # Initialize visited and topological order lists
    visited = [0] * n
    top_order = []

    # Function to perform depth-first search
    def dfs(node):
        visited[node] = 1
        for neighbor in adj_list[node]:
            if not visited[neighbor]:
                dfs(neighbor)
        top_order.append(node)

    # Perform depth-first search for all unvisited nodes
    for node in range(n):
        if not visited[node]:
            dfs(node)

    # Reverse the topological order to get lexicographically smallest order
    top_order.reverse()

    # Check for cycles
    for node in range(n):
        if (visited[node] > 1):
            return []

    return top_order
