def lex_topological_order(n: int, pairs: list[tuple[int, int]]) -> list[int]:
    # অনুযায়ী একটি জোড়া তৈরি করা
    graph = {i: [] for i in range(n)}
    # অনুযায়ী জোড়া তৈরি করা
    for a, b in pairs:
        graph[a].append(b)
    # তালিকা ফেরত সম্পূর্ণ করা
    topological_order = []
