    visited = [False] * n
    for node in range(n):
        if not visited[node]:
            stack = [node]
            while stack:
                current = stack.pop()
                if not visited[current]:
                    visited[current] = True
                    stack.extend(graph[current])
    # তালিকা ফেরত রিটার্ন করা
    return topological_order
