from collections import defaultdict

def find_bridges(n, edges):
    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    visited = [False]*n
    low = [float("Inf")]*n
    disc = [float("Inf")]*n
    parent = [-1]*n
