                if low[neighbour] > disc[node]:
                    bridges.append((node, neighbour))
            elif neighbour != parent[node]:
                low[node] = min(low[node], disc[neighbour])

    for node in range(n):
        if not visited[node]:
            dfs(node, 0)

    return sorted(bridges)
