def find_bridges(n: int, edges: list[tuple[int, int]]) -> list[tuple[int, int]]:
    graph = [[] for _ in range(n)]
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    visited = [False] * n
    low = [0] * n
    disc = [0] * n
    bridges = []
    time = 0

    def dfs(u, parent):
        nonlocal time
        visited[u] = True
        low[u] = disc[u] = time
        time += 1

        for v in graph[u]:
            if v == parent:
                continue
            if not visited[v]:
                dfs(v, u)
                low[u] = min(low[u], low[v])
                if low[v] > disc[u]:
                    bridges.append((u, v) if u < v else (v, u))
            else:
                low[u] = min(low[u], disc[v])

    for u in range(n):
        if not visited[u]:
            dfs(u, -1)

    return sorted(bridges)
