def lex_topological_order(n: int, pairs: list[tuple[int, int]]) -> list[int]:
    # অনুযায়ী সাইকেট তৈরি করা
    graph = {i: [] for i in range(n)}
    # অনুযায়ী সাইকেট পুনর্নিমিট করা
    for a, b in pairs:
        graph[a].append(b)
    # অনুযায়ী সাইকেট প্রতিটি নোড এর জন্য উপাদান বের করা
    visited = [False] * n
    # অনুযায়ী সাইকেট প্রতিটি নোড এর জন্য উপাদান বের করা
    topological_order = []
    for node in range(n):
        if not visited[node]:
            dfs(node, visited, graph, topological_order)
    # তালিকা রিটার্ন করা
    return topological_order

def dfs(node, visited, graph, topological_order):
    visited[node] = True
    for neighbour in graph[node]:
        if not visited[neighbour]:
            dfs(neighbour, visited, graph, topological_order)
    topological_order.insert(0, node)
