def identifier_to_snake(name: str) -> str:
    if not name:
        return ""
    words = []
    last_char = None
    for char in name:
        if char.isalnum():
            if last_char is None or not last_char.isalnum():
                words.append(char.lower())
            else:
                words[-1] += char.lower()
        elif char in {"_", "-"}:
            if last_char is not None and last_char.isalnum():
                words.append(char)
        last_char = char
    return "".join(words)
