def gcd(a, b):
    while b != 0:
        a, b = b, a % b
    return a

def lcm(a, b):
    return a * b // gcd(a, b)

def solve_congruences(congruences: list[tuple[int, int]]) -> tuple[int, int] | None:
    if not congruences:
        return 0, 1

    x, m = 0, 1
    for r, m_new in congruences:
        g = gcd(m, m_new)
        if (x % g != r % g):
            return None
        x += (r - x) % m_new * pow(m_new // g, -1, g) * m
        m = lcm(m, m_new)
        x %= m

    return x, m
