from collections import defaultdict

def lex_topological_order(n: int, pairs: list[tuple[int, int]]) -> list[int]:
    # Build the graph
    graph = defaultdict(list)
    for a, b in pairs:
        graph[a].append(b)

    # DFS
    visited = [0]*n
    stack = []
    def dfs(node):
        if visited[node] == 1:
            return
        visited[node] = 1
        for child in graph[node]:
            dfs(child)
        stack.append(node)

    # Visit all nodes
    for node in range(n):
        if visited[node] == 0:
            dfs(node)

    # Reverse the order
    stack.reverse()

    # Check for cycles
    if len(stack) != n:
        raise ValueError("Cycle detected in the graph")

    return stack

