def solve_congruences(congruences: list[tuple[int, int]]) -> tuple[int, int] | None:
    if not congruences:
        return 0, 1

    def gcd(a, b):
        while b:
            a, b = b, a % b
        return a

    def extended_gcd(a, b):
        if a == 0:
            return b, 0, 1
        else:
            g, x, y = extended_gcd(b % a, a)
            return g, y - (b // a) * x, x

    def mod_inverse(a, m):
        g, x, _ = extended_gcd(a, m)
        if g == 1:
            return x % m
        else:
            return None

    r = [r % m for r, m in congruences]
    M = [m for _, m in congruences]
    L = 1
    for m in M:
        L *= m

    x = 0
    for i in range(len(congruences)):
        Mi = L // M[i]
        xi = mod_inverse(Mi, M[i])
        if xi is None:
            return None
        x += r[i] * Mi * xi
    x %= L
    return x, L
