def lex_topological_order(n: int, pairs: list[tuple[int, int]]) -> list[int]:
    # Create adjacency list
    adj_list = {i: [] for i in range(n)}
    for a, b in pairs:
        adj_list[a].append(b)

    # Initialize visited and rec_stack
    visited = [False] * n
    rec_stack = [False] * n

    # Function to check cycle
    def is_cyclic(v):
        if visited[v] == False:
            visited[v] = True
            rec_stack[v] = True

            for neighbor in adj_list[v]:
                if visited[neighbor] == False and is_cyclic(neighbor) == True:
                    return True
                elif rec_stack[neighbor] == True:
                    return True

            rec_stack[v] = False

        return False

    # Check for cycles
    for v in range(n):
        if visited[v] == False:
            if is_cyclic(v) == True:
                return []

    # Perform topological sort
    topological_order = []
    for i in range(n):
        if visited[i] == False:
            stack = [i]
            while stack:
                node = stack[-1]
                if all(visited[j] for j in adj_list[node]):
                    visited[node] = True
                    topological_order.append(node)
                    stack.pop()
                else:
                    for neighbor in adj_list[node]:
                        if visited[neighbor] == False:
                            stack.append(neighbor)
                            break

    return topological_order
