from typing import List, Tuple

def solve_congruences(congruences: List[Tuple[int, int]]) -> Tuple[int, int] | None:
    if not congruences:
        return 0, 1

    def gcd(a, b):
        while b:
            a, b = b, a % b
        return a

    def lcm(a, b):
        return a * b // gcd(a, b)

    def extended_gcd(a, b):
        if a == 0:
            return b, 0, 1
        else:
            g, x, y = extended_gcd(b % a, a)
            return g, y - (b // a) * x, x

    def crt(r1, m1, r2, m2):
        g = gcd(m1, m2)
        if r1 % g != r2 % g:
            return None
        _, s, _ = extended_gcd(m1 // g, m2 // g)
        temp = (r2 - r1) // g * s % (m2 // g)
        return (r1 + m1 * temp) % lcm(m1, m2), lcm(m1, m2)

    result = (congruences[0][0], congruences[0][1])
    for r, m in congruences[1:]:
        result = crt(result[0], result[1], r, m)
        if result is None:
            return None
    return result
