            i += 1
            if i < len(encoded) and encoded[i] == '~':
                i += 1
                count = ""
                while i < len(encoded) and encoded[i].isdigit():
                    count += encoded[i]
                    i += 1
                count = int(count) if count else 1
                char = encoded[i]
                decoded += char * count
            else:
                decoded += encoded[i]
        else:
            decoded += encoded[i]
        i += 1
    return decoded
