import re

def identifier_to_snake(name: str) -> str:
    pieces = re.split('(?<=[a-z])(?=[A-Z])|(?<=[A-Z])(?=[A-Z][a-z])|(?<=[0-9])(?=[a-zA-Z])|(?<=[a-zA-Z])(?=[0-9])|_|-', name)
    words = [piece for piece in pieces if piece.isalpha()]
    return '_'.join(words).lower()

