def pack_bins(sizes: list[int], capacity: int) -> list[list[int]]:
    if any(size > capacity for size in sizes):
        raise ValueError("Item size exceeds capacity")
    bins = []
    for size in sizes:
        for bin in bins:
            if sum(bin) + size <= capacity:
                bin.append(size)
                break
        else:
            bins.append([size])
    return bins
