    blocked = set(blocked)
    def is_attack(i, j, blocked):
        for k in range(n):
            if (i, k) in blocked or (k, j) in blocked or \
               (k, k) in blocked and (i-k, j-k) in blocked and (i+k, j+k) in blocked and \
               (k, n-1-k) in blocked and (i-k, j+k) in blocked and (i+k, j-k) in blocked:
                return True
        return False

