    def search(i, cols, diagonals, anti_diagonals):
        if i == n:
            return 1
        count = 0
        for j in range(n):
            if (j not in cols and
                i-j not in diagonals and
                i+j not in anti_diagonals and
                (i, j) not in blocked):
                count += search(i+1, cols | {j}, diagonals | {i-j}, anti_diagonals | {i+j})
        return count
    return search(0, set(), set(), set())

