def pack_bins(sizes: list[int], capacity: int) -> list[list[int]]:
    if not all(i <= capacity for i in sizes):
        raise ValueError("One of the item sizes is larger than the capacity")
    sizes.sort(reverse=True)
    bins = []
    for size in sizes:
        for bin in bins:
            if sum(bin) + size <= capacity:
                bin.append(size)
                break
        else:
            bins.append([size])
    return bins
