def count_queens(n: int, blocked: list[tuple[int, int]]) -> int:
    if n < 1:
        return 1
    blocked = [(i, j) for i, j in blocked if 0 <= i < n and 0 <= j < n]
    blocked = set(blocked)
    def is_attacked(i: int, j: int, blocked: set) -> bool:
        for bi, bj in blocked:
            if bi == i or bj == j or abs(bi - i) == abs(bj - j):
                return True
        return False
    def count_arrangements(i: int, n: int, blocked: set) -> int:
        if i == n:
            return 1
        count = 0
        for j in range(n):
            if not is_attacked(i, j, blocked):
                count += count_arrangements(i + 1, n, blocked)
        return count
    return count_arrangements(0, n, blocked)
