def solve_congruences(congruences: list[tuple[int, int]]) -> tuple[int, int] | None:
    if not congruences:
        return (0, 1)

    def gcd(a, b):
        while b:
            a, b = b, a % b
        return a

    def extended_gcd(a, b):
        if a == 0:
            return (b, 0, 1)
        else:
            g, x, y = extended_gcd(b % a, a)
            return (g, y - (b // a) * x, x)

    def mod_inverse(a, m):
        g, x, _ = extended_gcd(a, m)
        if g == 1:
            return x % m
        else:
            return None

    r, m = congruences[0]
    for r_i, m_i in congruences[1:]:
        g = gcd(m, m_i)
        if (r % g) != (r_i % g):
            return None
        r = (r * (m_i // g) * mod_inverse(m // g, m_i // g)) % (m * m_i // g)
        m *= m_i // g

    return (r, m)
