def solve_congruences(congruences: list[tuple[int, int]]) -> tuple[int, int] | None:
    if not congruences:
        return (0, 1)

    def gcd(a, b):
        while b:
            a, b = b, a % b
        return a

    def lcm(a, b):
        return a * b // gcd(a, b)

    r, m = congruences[0]
    for new_r, new_m in congruences[1:]:
        while r % new_m != new_r % new_m:
            r += m
        g = gcd(m, new_m)
        l = lcm(m // g, new_m // g)
        r = r * (l // m) % l
        m = l

    return (r % m, m) if m else (0, 1)
