def stabilize_sandpile(grid: list[list[int]]) -> list[list[int]]:
    rows, cols = len(grid), len(grid[0])
    new_grid = [[0]*cols for _ in range(rows)]
    stack = []

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] >= 4:
                new_grid[r][c] = grid[r][c] - 4
                if r > 0:
                    stack.append((r-1, c))
                if c > 0:
                    stack.append((r, c-1))
                if r < rows - 1:
                    stack.append((r+1, c))
                if c < cols - 1:
                    stack.append((r, c+1))

