def decode_runs(encoded: str) -> str:
    decoded = ""
    i = 0
    while i < len(encoded):
        if encoded[i] == '\\':
            i += 1
            if encoded[i] == '~':
                i += 1
                count = ""
                while encoded[i].isdigit():
                    count += encoded[i]
                    i += 1
                count = int(count) if count else 1
                char = encoded[i]
                decoded += char * count
            else:
                decoded += encoded[i]
        else:
            decoded += encoded[i]
        i += 1
    return decoded

