def solve_congruences(congruences: list[tuple[int, int]]) -> tuple[int, int] | None:
    if not congruences:
        return 0, 1

    def gcd(a, b):
        while b:
            a, b = b, a % b
        return a

    def extended_gcd(a, b):
        if a == 0:
            return b, 0, 1
        else:
            g, x, y = extended_gcd(b % a, a)
            return g, y - (b // a) * x, x

    def mod_inverse(a, m):
        g, x, _ = extended_gcd(a, m)
        if g == 1:
            return x % m
        else:
            return None

    M = 1
    for _, m in congruences:
        M *= m

    x = 0
    for r, m in congruences:
        Mi = M // m
        xi = mod_inverse(Mi, m)
        x += r * Mi * xi

    L = M // gcd(x, M)
    x %= L

    return x, L
