def solve_congruences(congruences: list[tuple[int, int]]) -> tuple[int, int] | None:
    if not congruences:
        return (0, 1)

    def gcd(a, b):
        while b:
            a, b = b, a % b
        return a

    def extended_gcd(a, b):
        if a == 0:
            return (b, 0, 1)
        else:
            g, x, y = extended_gcd(b % a, a)
            return (g, y - (b // a) * x, x)

    def mod_inverse(a, m):
        g, x, _ = extended_gcd(a, m)
        if g == 1:
            return x % m
        else:
            return None

    r1, m1 = congruences[0]
    for r2, m2 in congruences[1:]:
        g = gcd(m1, m2)
        if (r1 - r2) % g != 0:
            return None
        lcm = m1 * m2 // g
        x = (r1 * (m2 // g) * mod_inverse(m1 // g, m2 // g)) % lcm
        r1 = x
        m1 = lcm

    return (r1 % m1, m1)
