def subsets_with_sum(nums: list[int], k: int) -> list[list[int]]:
    def dfs(nums, target, path, add):
        if target < 0:
            return  # backtracking
        if target == 0:
            result.append(path)
            return 
        for i in range(len(nums)):
            # i > start_index ensures that we don't reuse the same number
            # if we have duplicate numbers in nums
            if i > add:
                break
            # choose
            dfs(nums, target-nums[i], path+[nums[i]], i+1)

    result = []
    nums.sort()
    dfs(nums, k, [], 0)
    return result
