def weighted_edit_cost(source: str, target: str, insert_cost: int, delete_cost: int, replace_cost: int) -> int:
    m, n = len(source), len(target)
    dp = [[0] * (n+1) for _ in range(m+1)]

    for i in range(m+1):
        for j in range(n+1):
            if i == 0:
                dp[i][j] = j * insert_cost
            elif j == 0:
                dp[i][j] = i * delete_cost
            elif source[i-1] == target[j-1]:
                dp[i][j] = dp[i-1][j-1]
            else:
                dp[i][j] = min(dp[i-1][j] + delete_cost, dp[i][j-1] + insert_cost, dp[i-1][j-1] + replace_cost)

    return dp[m][n]
