from collections import defaultdict, deque

def lex_topological_order(n: int, pairs: list[tuple[int, int]]) -> list[int]:
    if n == 0:
        return []
    graph = defaultdict(list)
    in_degree = [0]*n
    for a, b in pairs:
        graph[a].append(b)
        in_degree[b] += 1
    zero_in_degree = deque()
    for i in range(n):
        if in_degree[i] == 0:
            zero_in_degree.append(i)
    order = []
    while zero_in_degree:
        u = zero_in_degree.popleft()
        order.append(u)
        for v in graph[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                zero_in_degree.append(v)
    if len(order) == n:
        return order
    else:
        return []
