def lex_topological_order(n: int, pairs: list[tuple[int, int]]) -> list[int]:
    if n == 0:
        return []
    graph = {i: [] for i in range(n)}
    indegree = {i: 0 for i in range(n)}
    for a, b in pairs:
        if a == b:
            return []
        graph[a].append(b)
        indegree[b] += 1
    min_heap = [i for i in range(n) if indegree[i] == 0]
    heapq.heapify(min_heap)
    order = []
    while min_heap:
        node = heapq.heappop(min_heap)
        order.append(node)
        for neighbor in graph[node]:
            indegree[neighbor] -= 1
            if indegree[neighbor] == 0:
                heapq.heappush(min_heap, neighbor)
    return order if len(order) == n else []
