def pack_bins(sizes: list[int], capacity: int) -> list[list[int]]:
    if not sizes:
        return []
    if any(size > capacity for size in sizes):
        raise ValueError("Item size is larger than bin capacity")
    sizes.sort(reverse=True)
    bins = []
    for size in sizes:
        for bin in bins:
            if sum(bin) + size <= capacity:
                bin.append(size)
                break
        else:
            bins.append([size])
    return bins
