def pack_bins(sizes: list[int], capacity: int) -> list[list[int]]:
    if not all(0 < size <= capacity for size in sizes):
        raise ValueError("All item sizes must be between 1 and capacity.")
    bins = []
    for size in sorted(sizes, reverse=True):
        for bin in bins:
            if sum(bin) + size <= capacity:
                bin.append(size)
                break
        else:
            bins.append([size])
    return bins
