    if not 2 <= from_base <= 36 or not 2 <= to_base <= 36:
        raise ValueError("Invalid base")

    if number == "-":
        return "-"

    if number == "0":
        return "0"

    if not all(('0' <= c <= '9' or 'a' <= c <= 'z' or 'A' <= c <= 'Z') for c in number):
        raise ValueError("Invalid character in number")

    if from_base == 10:
        digits = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"[:to_base]
        base = to_base
    else:
