    for job in jobs:
        if not isinstance(job, dict):
            raise ValueError('Each job must be a dictionary')

        if 'name' not in job or not isinstance(job['name'], str):
            raise ValueError('Each job must have a "name" key with a string value')

        if 'interval' not in job or not isinstance(job['interval'], int):
            raise ValueError('Each job must have an "interval" key with an integer value')

        if 'enabled' not in job:
