def tidy_punctuation(text: str) -> str:
    # Step 1: Replace multiple whitespaces with single space
    text = ' '.join(text.split())

    # Step 2: Replace punctuation followed by space with space
    for punctuation in [',', '.', ';', ':', '!', '?']:
        text = text.replace(punctuation + ' ', punctuation)

    # Step 3: Add space after punctuation if next character is a letter
    for punctuation in [',', '.', ';', ':', '!', '?']:
        text = text.replace(punctuation, punctuation + ' ')

    # Step 4: Convert first character and characters after punctuation to uppercase
    text = text[0].upper() + text[1:]
    for i in range(1, len(text)):
        if text[i] in ['.', '!', '?']:
            text = text[:i+1] + text[i+1].upper() + text[i+2:]

    return text

