def expand_template(template: str, values: dict[str, str]) -> str:
    start = template.find('{{')
    while start != -1:
        end = template.find('}}', start)
        if end == -1:
            break
        key = template[start+2:end].strip()
        template = template[:start] + values.get(key, '{{'+key+'}}') + template[end+2:]
        start = template.find('{{', start+1)
    return template

