def convert_base(number: str, from_base: int, to_base: int) -> str:
    if not 2 <= from_base <= 36 or not 2 <= to_base <= 36:
        raise ValueError("Both from_base and to_base must be between 2 and 36")

    if number == '-':
        return '-'

    if number == '0':
        return '0'

    if not all(('0' <= char <= '9' or 'a' <= char <= 'z') and char.lower() <= ('a' * (from_base <= 36) + '9' * (from_base > 36)) for char in number.lower()):
        raise ValueError("Invalid character in number for specified from_base")

    base10 = int(number, from_base)
    if to_base == 10:
        return str(base10)

    if base10 == 0:
        return '0'

    chars = '0123456789abcdefghijklmnopqrstuvwxyz'[:to_base]
    result = ''
    while base10:
        base10, digit = divmod(base10, to_base)
        result = chars[digit] + result
    return result
