from itertools import permutations

def seating_arrangements(guests: list[str], conflicts: list[tuple[str, str]]) -> list[list[str]]:
    if not guests:
        return [[]]

    conflicts_dict = {a: b for a, b in conflicts}
    conflicts_dict.update({b: a for a, b in conflicts})

    def is_valid(seating):
        for i in range(len(seating) - 1):
            if seating[i+1] == conflicts_dict.get(seating[i]):
                return False
        return True

    all_seatings = permutations(guests)
    valid_seatings = [seating for seating in all_seatings if is_valid(seating)]

    return valid_seatings
