def seating_arrangements(guests, conflicts):
    conflicts_dict = {guest: set() for guest in guests}
    for conflict in conflicts:
        a, b = conflict
        conflicts_dict[a].add(b)
        conflicts_dict[b].add(a)

    def dfs(guest_index, guests, conflicts_dict, arrangement):
        if guest_index == len(guests):
