        number = number[1:]

    if not all(("0" <= char <= "9") or ("a" <= char.lower() <= "z") for char in number):
        raise ValueError("Invalid character in number")

    max_char = max(number)
    if "0" <= max_char <= "9":
        n = int(number, from_base)
    else:
