def expand_template(template: str, values: dict[str, str]) -> str:
    result = ""
    i = 0
    while i < len(template):
        if template[i:i+2] == "{{":
            result += "{"
            i += 2
        elif template[i:i+2] == "}}":
            result += "}"
            i += 2
        elif template[i] == "{":
            end = template.find("}", i)
            if end == -1:
                result += template[i:]
                break
            key = template[i+1:end].strip()
            result += values.get(key, template[i:end+1])
            i = end + 1
        else:
            result += template[i]
            i += 1
    return result
