from itertools import permutations

def seating_arrangements(guests: list[str], conflicts: list[tuple[str, str]]) -> list[list[str]]:
    conflicts_dict = {a: set(b) for a, b in conflicts}
    for guest in guests:
        if guest not in conflicts_dict:
            conflicts_dict[guest] = set()

    arrangements = []
    for perm in permutations(guests):
        if all(perm[i] not in conflicts_dict[perm[i+1]] for i in range(len(perm)-1)):
            arrangements.append(list(perm))

    return arrangements if arrangements else []
