    if to_base == 2:
        return bin(dec_value)[2:]
    return base_conversion(dec_value, 10, to_base, digits)

def base_conversion(number, from_base, to_base, digits):
    if number < to_base:
        return digits[number]
    else:
        return base_conversion(number // to_base, from_base, to_base, digits) + digits[number % to_base]
