def free_slots(busy: list[tuple[int, int]], day_start: int, day_end: int, min_len: int) -> list[tuple[int, int]]:
    if day_start >= day_end:
        return []
    busy = [(max(start, day_start), min(end, day_end)) for start, end in busy if start < end]
    busy.sort()
    gaps = [(day_start, busy[0][0])] if busy[0][0] > day_start else []
    for i in range(len(busy) - 1):
        if busy[i + 1][0] > busy[i][1]:
            gaps.append((busy[i][1], busy[i + 1][0]))
        elif busy[i + 1][0] == busy[i][1]:
            gaps[len(gaps) - 1] = (gaps[len(gaps) - 1][0], busy[i + 1][1])
    if busy[-1][1] < day_end:
        gaps.append((busy[-1][1], day_end))
    return [(start, end) for start, end in gaps if end - start >= min_len]
