def convert_base(number: str, from_base: int, to_base: int) -> str:
    if not 2 <= from_base <= 36 or not 2 <= to_base <= 36:
        raise ValueError("Bases must be between 2 and 36")

    if not number or number == '-':
        raise ValueError("Number cannot be empty or '-'")

    if number[0] == '-':
        negative = True
        number = number[1:]
    else:
        negative = False

    if not all(c.isdigit() or 'a' <= c.lower() <= 'z' for c in number):
        raise ValueError("Invalid digit for from_base")

    max_digit = max(number.lower())
    if max_digit.isdigit():
        max_digit = int(max_digit)
    else:
        max_digit = ord(max_digit) - ord('a') + 10

    if max_digit >= from_base:
        raise ValueError("Invalid digit for from_base")

    base10 = sum(int(number[i]) * (from_base ** (len(number) - i - 1)) if number[i].isdigit() 
                  else (ord(number[i].lower()) - ord('a') + 10) * (from_base ** (len(number) - i - 1)) 
                  for i in range(len(number)))

    if to_base == 10:
        return '-' + str(base10) if negative else str(base10)

    digits = []
    while base10:
        base10, remainder = divmod(base10, to_base)
        digits.append(str(remainder))

    result = ''.join(digits[::-1])
    return '-' + result if negative else result
