        elif busy[i][1] == busy[i + 1][0]:
            free.append((busy[i][1], busy[i + 1][1]))
    if busy[-1][1] < day_end:
        free.append((busy[-1][1], day_end))

    return [(start, end) for start, end in free if end - start >= min_len]

