from itertools import permutations

def seating_arrangements(guests: list[str], conflicts: list[tuple[str, str]]) -> list[list[str]]:
    conflicts_set = set(conflicts)
    valid_arrangements = []

    def backtrack(path, used):
        if len(path) == len(guests):
            valid_arrangements.append(path[:])
            return

        for guest in guests:
            if guest in used:
                continue

            if path and path[-1] > guest:
                continue

            if (path[-1] if path else '', guest) in conflicts_set:
                continue

            path.append(guest)
            used.add(guest)
            backtrack(path, used)
            path.pop()
            used.remove(guest)

    backtrack([], set())
    valid_arrangements.sort()
    return valid_arrangements

