import operator
import ast

def matches_filter(expression: str, record: dict) -> bool:
    # Define the operators
    operators = {ast.Add: operator.add, ast.Sub: operator.sub,
                  ast.Mult: operator.mul, ast.Div: operator.truediv,
                  ast.USub: operator.neg, ast.BitAnd: operator.and_,
                  ast.BitOr: operator.or_, ast.BitXor: operator.xor,
                  ast.Lt: operator.lt, ast.Le: operator.le,
                  ast.Gt: operator.gt, ast.Ge: operator.ge,
                  ast.Eq: operator.eq, ast.Ne: operator.ne,
                  ast.Not: operator.not_, ast.And: operator.and_,
                  ast.Or: operator.or_}

    # Parse the expression
    try:
        expr_ast = ast.parse(expression, mode='eval').body
    except SyntaxError:
        raise ValueError("Invalid expression")

    # Recursively evaluate the expression
    def evaluate(node):
        if isinstance(node, ast.Num):
            return node.n
        elif isinstance(node, ast.BinOp):
            return operators[type(node.op)](evaluate(node.left), evaluate(node.right))
        elif isinstance(node, ast.UnaryOp):
            return operators[type(node.op)](evaluate(node.operand))
        elif isinstance(node, ast.Name):
            if node.id in record:
                return record[node.id]
            else:
                raise ValueError("Invalid expression")
        else:
            raise ValueError("Invalid expression")

    return evaluate(expr_ast) != 0
