import math
import ast
import operator as op

def evaluate_formula(formula: str, x: float) -> float:
    operators = {ast.Add: op.add, ast.Sub: op.sub, ast.Mult: op.mul,
                 ast.Div: op.truediv, ast.Pow: op.pow, ast.BitXor: op.xor,
                 ast.USub: op.neg}

    functions = {
        'sqrt': math.sqrt,
        'abs': abs,
        'sin': math.sin,
        'cos': math.cos
    }

    parsed = ast.parse(formula, mode='eval').body

    if not isinstance(parsed, (ast.BinOp, ast.Compare, ast.Add, ast.Sub, ast.Mult, ast.Div, ast.USub, ast.Pow, ast.BitXor, ast.Call)):
        raise ValueError("Invalid formula")

    def _evaluate(node):
        if isinstance(node, ast.Num):
            return node.n
        elif isinstance(node, ast.BinOp):
            return operators[type(node.op)](_evaluate(node.left), _evaluate(node.right))
        elif isinstance(node, ast.Call):
            args = [_evaluate(arg) for arg in node.args]
            if node.func.id in functions:
                return functions[node.func.id](*args)
            else:
                raise ValueError("Invalid function")
        elif isinstance(node, ast.Name):
            if node.id == 'x':
                return x
            else:
                raise ValueError("Invalid variable")
        else:
            raise ValueError("Invalid formula")

    return _evaluate(parsed)
