import math
import ast
import operator as op

OPERATORS = {ast.Add: op.add, ast.Sub: op.sub, ast.Mult: op.mul,
             ast.Div: op.truediv, ast.Pow: op.pow, ast.USub: op.neg}

def evaluate_formula(formula: str, x: float) -> float:
    try:
        return eval_expr(ast.parse(formula, mode='eval').body, x)
    except Exception as e:
        raise ValueError("Invalid formula") from e

def eval_expr(node, x):
    if isinstance(node, ast.Num):
        return node.n
    elif isinstance(node, ast.BinOp):  
        return OPERATORS[type(node.op)](eval_expr(node.left, x), eval_expr(node.right, x))
    elif isinstance(node, ast.UnaryOp):  
        return OPERATORS[type(node.op)](eval_expr(node.operand, x))
    elif isinstance(node, ast.NameConstant):
        return node.value
    elif isinstance(node, ast.Call):  
        if node.func.id == 'sqrt':
            return math.sqrt(eval_expr(node.args[0], x))
        elif node.func.id == 'abs':
            return abs(eval_expr(node.args[0], x))
        elif node.func.id == 'sin':
            return math.sin(math.radians(eval_expr(node.args[0], x)))
        elif node.func.id == 'cos':
            return math.cos(math.radians(eval_expr(node.args[0], x)))
    else:
        raise ValueError("Invalid formula")
