    # Sort the jobs in decreasing order of profit
    jobs.sort(key=lambda x: x[2], reverse=True)

    # Initialize the result list with empty slots
    result = [''] * len(jobs[0][1])

    # Iterate over the jobs
    for job in jobs:
        # Try to find a slot for the job
        for i in range(min(len(result), job[1]-1), -1, -1):
            if result[i] == '':
                result[i] = job[0]
                break

    return result

def schedule_jobs(jobs: list[tuple[str, int, int]]) -> list[str]:
    # Sort jobs by profit in descending order
    jobs.sort(key=lambda x: x[2], reverse=True)

    # Initialize a list to store the scheduled jobs
    scheduled_jobs = [None] * jobs[0][1]

    # Schedule jobs
    for job in jobs:
        for i in range(job[1]-1, -1, -1):
            if scheduled_jobs[i] is None:
                scheduled_jobs[i] = job[0]
                break

    # Return the scheduled jobs
    return scheduled_jobs

