def free_slots(busy: list[tuple[int, int]], day_start: int, day_end: int, min_len: int) -> list[tuple[int, int]]:
    if day_start >= day_end:
        return []

    busy = sorted([b for b in busy if b[0] < day_end and b[1] > day_start])
    merged = [busy[0]]

    for i in range(1, len(busy)):
        if merged[-1][1] >= busy[i][0] and merged[-1][1] < busy[i][1]:
            merged[-1] = (merged[-1][0], busy[i][1])
        elif merged[-1][1] < busy[i][0]:
            merged.append(busy[i])

    free = [(day_start, merged[0][0])] if merged[0][0] > day_start else []
    for i in range(1, len(merged)):
        if merged[i-1][1] < merged[i][0]:
            free.append((merged[i-1][1], merged[i][0]))
        if merged[i][1] > day_end:
            break
    free.append((merged[-1][1], day_end) if merged[-1][1] < day_end else ())

    return [f for f in free if f[1] - f[0] >= min_len]
