def parse_csv(text: str) -> list[list[str]]:
    if not text:
        return []
    lines = text.split('\n')
    records = []
    for line in lines:
        fields = []
        field = ''
        quoted = False
        for ch in line:
            if ch == '"':
                quoted = not quoted
                continue
            if ch == ',' and not quoted:
                fields.append(field.strip())
                field = ''
                continue
            field += ch
        if field:
            fields.append(field.strip())
        records.append(fields)
    return records

