def free_slots(busy: list[tuple[int, int]], day_start: int, day_end: int, min_len: int) -> list[tuple[int, int]]:
    if day_start >= day_end:
        return []
    busy.sort()
    slots = [(day_start, min(busy[0][0], day_end))] if busy and busy[0][0] > day_start else [(day_start, day_end)]
    for start, end in busy:
        if start > slots[-1][1]:
            slots.append((slots[-1][1], min(end, day_end)))
        elif end > slots[-1][1]:
            slots[-1] = (slots[-1][0], end)
    return [slot for slot in slots if slot[1] - slot[0] >= min_len]
