def rotate_rings(matrix: list[list[int]], k: int) -> list[list[int]]:
    if not matrix:
        return []

    n = len(matrix)
    m = n // 2 if n % 2 == 0 else n // 2 + 1
    k = k % (2 * (n - 1))

    def rotate_ring(start, end):
        if start >= end:
            return
        temp = matrix[start][start]
        for i in range(start + 1, end + 1):
            matrix[start][i - 1], temp = temp, matrix[start][i - 1]
        for i in range(start + 1, end + 1):
            matrix[i - 1][end], temp = temp, matrix[i - 1][end]
        for i in range(end - 1, start - 1, -1):
            matrix[end][i + 1], temp = temp, matrix[end][i + 1]
        for i in range(end - 1, start, -1):
            matrix[i + 1][start], temp = temp, matrix[i + 1][start]

    for i in range(m):
        if k > 0:
            rotate_ring(i, n - i - 1)
        else:
            rotate_ring(i, n - i - 1)

    return matrix
