def league_table(results: list[tuple[str, str, int, int]]) -> list[tuple[str, int, int, int]]:
    if not results:
        return []
    team_points = {}
    team_goal_diff = {}
    team_goals = {}
    for match in results:
        home, away, home_goals, away_goals = match
        if home not in team_points:
            team_points[home] = 0
            team_goal_diff[home] = 0
            team_goals[home] = 0
        if away not in team_points:
            team_points[away] = 0
            team_goal_diff[away] = 0
            team_goals[away] = 0
        team_goals[home] += home_goals
        team_goals[away] += away_goals
        if home_goals > away_goals:
            team_points[home] += 3
            team_goal_diff[home] += home_goals - away_goals
        elif home_goals < away_goals:
            team_points[away] += 3
            team_goal_diff[away] += away_goals - home_goals
        else:
            team_points[home] += 1
            team_points[away] += 1
            team_goal_diff[home] += home_goals - away_goals
            team_goal_diff[away] += away_goals - home_goals
    return sorted([(team, team_points[team], team_goal_diff[team], team_goals[team]) for team in team_points], key=lambda x: (-x[1], -x[2], -x[3], x[0]))
