import heapq

def cheapest_route(edges: list[tuple[str, str, int]], start: str, goal: str) -> tuple[int, list[str]] | None:
    graph = {}
    for u, v, w in edges:
        if u not in graph:
            graph[u] = []
        if v not in graph:
            graph[v] = []
        graph[u].append((v, w))
        graph[v].append((u, w))

    queue = [(0, start, [start])]
    visited = {start: 0}

    while queue:
        (cost, node, path) = heapq.heappop(queue)
        if node not in visited or cost < visited[node]:
            visited[node] = cost
            if node == goal:
                return cost, path
            for (next_node, next_cost) in graph.get(node, []):
                if next_node not in visited or cost + next_cost < visited[next_node]:
                    visited[next_node] = cost + next_cost
                    heapq.heappush(queue, (cost + next_cost, next_node, path + [next_node]))
    return None
