def schedule_jobs(jobs: list[tuple[str, int, int]]) -> list[str]:
    # Sort the jobs in decreasing order of profit
    jobs.sort(key=lambda x: x[2], reverse=True)

    # Initialize the result list with empty slots
    result = [''] * max(job[1] for job in jobs)

    # Schedule the jobs
    for job in jobs:
        for i in range(job[1]-1, -1, -1):
            if result[i] == '':
                result[i] = job[0]
                break

    return result

def teller_waits(arrivals: list[int], service_times: list[int], tellers: int) -> list[int]:
    if not arrivals or not service_times:
        return []

    events = [(arrivals[i], service_times[i]) for i in range(len(arrivals))]
    events.sort()

    available_tellers = [0] * tellers
    wait_times = [0] * len(arrivals)

    for i, (arrival, service_time) in enumerate(events):
        earliest_free_time = min(available_tellers)
        if arrival < earliest_free_time:
            wait_times[i] = earliest_free_time - arrival
            available_tellers[available_tellers.index(earliest_free_time)] += service_time
        else:
            available_tellers[i % tellers] = arrival + service_time

    return wait_times

