    n = len(matrix)
    m = len(matrix[0])
    new_matrix = [[0]*m for _ in range(n)]
    k = min(k, n*m)

    for i in range(n//2):
        for j in range(i, m-i-1):
            ring = []
            # প্রতিটি বলয় পেতে যাবে
