def rotate_rings(matrix: list[list[int]], k: int) -> list[list[int]]:
    n = len(matrix)
    m = len(matrix[0])
    layers = min(n, m) // 2

    for l in range(layers):
        ring_size = 2 * (n - 2 * l) + 2 * (m - 2 * l) - 4
        rotate_count = k % ring_size

        # Save the elements of the ring in a list
        ring = []
        for i in range(l, n - l):
            ring.append(matrix[l][i])
        for i in range(l + 1, m - l):
            ring.append(matrix[i][m - l - 1])
        for i in range(l + 1, n - l):
            ring.append(matrix[n - l - 1][m - i - 1])
        for i in range(l + 1, m - l - 1):
            ring.append(matrix[n - i - 1][l])

        # Rotate the ring
        ring = ring[-rotate_count:] + ring[:-rotate_count]

        # Put the elements back into the matrix
        for i, val in enumerate(ring):
            matrix[l][i + l] = val
        for i, val in enumerate(ring[ring_size // 4:] + ring[:ring_size // 4]):
            matrix[i + l][m - l - 1] = val
        for i, val in enumerate(ring[2 * (ring_size // 4):] + ring[:2 * (ring_size // 4)]):
            matrix[n - l - 1][m - i - 1] = val
        for i, val in enumerate(ring[3 * (ring_size // 4):] + ring[:3 * (ring_size // 4)]):
            matrix[n - i - 1][l] = val

    return matrix
