def rotate_rings(matrix: list[list[int]], k: int) -> list[list[int]]:
    n = len(matrix)
    m = len(matrix[0])
    layers = min(n, m) // 2

    for l in range(layers):
        ring_size = 2 * (n - 2 * l) + 2 * (m - 2 * l) - 4
        rotate_count = k % ring_size

        # Save the ring in a list
        ring = []
        for i in range(l, n - l):
            if i == l or i == n - l - 1:
                for j in range(l, m - l):
                    if j == l or j == m - l - 1:
                        ring.append(matrix[i][j])
            else:
                ring.append(matrix[i][l])
                ring.append(matrix[i][m - l - 1])

        # Rotate the ring
        ring = ring[-rotate_count:] + ring[:-rotate_count]

        # Put the ring back into the matrix
        index = 0
        for i in range(l, n - l):
            if i == l or i == n - l - 1:
                for j in range(l, m - l):
                    if j == l or j == m - l - 1:
                        matrix[i][j] = ring[index]
                        index += 1
            else:
                matrix[i][l] = ring[index]
                index += 1
                matrix[i][m - l - 1] = ring[index]
                index += 1

    return matrix
