import re

def tokenize_code(source: str) -> list[tuple[str, str]]:
    token_specification = [
        ("NUMBER",   r"\d+(\.\d*)?"),
        ("NAME",     r"[a-zA-Z][a-zA-Z0-9_]*"),
        ("OP",       r"[+\-*/=<>()\[\],]|(<=)|(>=)"),
        ("SKIP",     r"\s+"),
        ("MISMATCH", r"."),
    ]
    tok_regex = '|'.join('(?P<%s>%s)' % pair for pair in token_specification)
    for mo in re.finditer(tok_regex, source):
        kind = mo.lastgroup
        if kind == "SKIP":
            continue
        elif kind == "MISMATCH":
            raise ValueError('Invalid character %s' % mo.group())
        else:
            yield (kind, mo.group())
