def rotate_rings(matrix: list[list[int]], k: int) -> list[list[int]]:
    if not matrix or len(matrix) == 0:
        return []

    n = len(matrix)
    m = n // 2
    k = k % (2 * n - 4) if n > 1 else 0

    def rotate_ring(start: int, end: int) -> None:
        if start >= end:
            return

        size = end - start
        temp = [0] * size

        # Store the top row
        for i in range(start, end):
            temp[i - start] = matrix[start][i]

        # Move left column to top
        for i in range(start, end):
            matrix[i][start] = matrix[end - 1][i]

        # Move bottom row to left column
        for i in range(start, end):
            matrix[end - 1][i] = matrix[end - 1 - i + start][end - 1]

        # Move right column to bottom
        for i in range(start, end - 1, -1):
            matrix[i][end - 1] = matrix[start][i]

        # Restore top row
        for i in range(start, end):
            matrix[start][i] = temp[i - start]

    for i in range(m):
        if k > 0:
            rotate_ring(i, n - i)
        else:
            rotate_ring(i, n - i - 1)

    return matrix
