def cheapest_route(edges: list[tuple[str, str, int]], start: str, goal: str) -> tuple[int, list[str]] | None:
    graph = {}
    for u, v, w in edges:
        if u not in graph:
            graph[u] = []
        if v not in graph:
            graph[v] = []
        graph[u].append((v, w))
        graph[v].append((u, w))

    queue = [(0, start, [start])]
    visited = {start: 0}
    while queue:
        cost, node, path = heapq.heappop(queue)
        if node == goal:
            return (cost, path)
