import re

def is_local_redirect(target: str, host: str) -> bool:
    if not target or len(target) > 2000 or '\t' in target or '\n' in target or '\r' in target or '\\' in target or ' ' in target or any(ord(c) < 32 or ord(c) > 127 for c in target):
        return False
    if target[0] == '/':
        return True
    if target.startswith('http://') or target.startswith('https://'):
        url_match = re.match(r'^(?:http|https)://([^/]+)', target)
        return url_match is not None and url_match.group(1).lower() == host.lower()
    return False
