def schedule_jobs(jobs: list[tuple[str, int, int]]) -> list[str]:
    # Sort the jobs in decreasing order of profit
    jobs.sort(key=lambda x: x[2], reverse=True)

    # Initialize the time slots
    slots = [None] * max(job[1] for job in jobs)

    # Schedule the jobs
    for job in jobs:
        for i in range(min(job[1], len(slots))):
            if slots[i] is None:
                slots[i] = job[0]
                break

    # Return the scheduled jobs
