def min_slides(grid: list[str]) -> int:
    rows, cols = len(grid), len(grid[0])
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]  # right, down, left, up
    visited = [[0]*cols for _ in range(rows)]
    start, end = None, None

    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 'S':
                start = (i, j, 0)  # (row, col, steps)
            elif grid[i][j] == 'E':
                end = (i, j)

    if start is None or end is None:
        return -1

    queue = deque([start])
    visited[start[0]][start[1]] = 1

    while queue:
        curr_row, curr_col, steps = queue.popleft()

        if (curr_row, curr_col) == end:
            return steps

        for d in directions:
            next_row, next_col = curr_row + d[0], curr_col + d[1]

            if 0 <= next_row < rows and 0 <= next_col < cols and grid[next_row][next_col] != '#' and not visited[next_row][next_col]:
                queue.append((next_row, next_col, steps+1))
                visited[next_row][next_col] = 1

    return -1
