def rotate_rings(matrix: list[list[int]], k: int) -> list[list[int]]:
    if not matrix:
        return []

    n = len(matrix)
    new_matrix = [[0]*n for _ in range(n)]
    for i in range(n//2):
        for j in range(i, n-i-1):
            ring_length = 2*(n-2*i-1)
            new_pos = (j-i+k)%ring_length
            if new_pos < n-2*i-1:
                new_matrix[i][j] = matrix[i][j+1]
                new_matrix[j][n-i-1] = matrix[j+1][n-i-1]
                new_matrix[n-i-1][n-j-1] = matrix[n-i-1][n-j-2]
                new_matrix[n-j-1][i] = matrix[n-i-2][i]
            else:
                new_matrix[i][j] = matrix[i+1][j]
                new_matrix[j][n-i-1] = matrix[n-i-2][n-i-1]
                new_matrix[n-i-1][n-j-1] = matrix[n-i-1][n-j-2]
                new_matrix[n-j-1][i] = matrix[n-i-2][i]
    if n%2:
        new_matrix[n//2][n//2] = matrix[n//2][n//2]
    return new_matrix

