    tok_regex = '|'.join('(?P<%s>%s)' % pair for pair in token_spec)
    for mo in re.finditer(tok_regex, source):
        kind = mo.lastgroup
        if kind == "SKIP":
            continue
        elif kind == "NUMBER" or kind == "NAME":
            text = mo.group(kind)
            if any(char.isalpha() or char.isdigit() or char == '_' for char in text):
