        else:
            text = mo.group(kind)
        tokens.append((kind, text))
    return tokens

import re

def tokenize_code(source: str) -> list[tuple[str, str]]:
    tokens = []
    source = source.replace(' ', '').replace('\t', '').replace('\n', '')
    while source:
        if source[0].isdigit():
            match = re.match(r'\d+(\.\d+)?', source)
            tokens.append(('NUMBER', match.group(0)))
            source = source[match.end():]
        elif source[0].isalpha() or source[0] == '_':
            match = re.match(r'\w+', source)
            tokens.append(('NAME', match.group(0)))
            source = source[match.end():]
        elif source[:2] in ['==', '!=', '<=', '>=', '+', '-', '*', '/', '<', '>', '=', '(', ')', ',']:
            tokens.append(('OP', source[0:2] if source[:2] in ['==', '!=', '<=', '>='] else source[0]))
            source = source[1 if source[0] in ['+', '-', '*', '/', '<', '>', '=', '(', ')', ',' ] else 2:]
        else:
            raise ValueError("Invalid character in source code")
    return tokens

