def format_table(rows: list[list[str]], aligns: str) -> str:
    if not rows:
        return ""

    # Calculate the width of each column
    widths = [max(len(cell) for cell in col) for col in zip(*rows)]

    # Format each row
    formatted_rows = []
    for row in rows:
        formatted_cells = []
        for i, cell in enumerate(row):
            align = aligns[i % len(aligns)]
            if align == 'l':
                formatted_cells.append(cell.ljust(widths[i]))
            elif align == 'r':
                formatted_cells.append(cell.rjust(widths[i]))
            elif align == 'c':
                formatted_cells.append(cell.center(widths[i]))
        formatted_rows.append(" | ".join(formatted_cells))

    return "\n".join(formatted_rows)
