def tokenize_code(source: str) -> list[tuple[str, str]]:
    tokens = []
    source = source.replace('\t', ' ').replace('\n', ' ')
    while '  ' in source:
        source = source.replace('  ', ' ')
    source = source.split(' ')
    for s in source:
        if s == '':
            continue
        if re.match(r'^[0-9]*(\.[0-9]+)?$', s):
            tokens.append(('NUMBER', s))
        elif re.match(r'^[a-zA-Z_][a-zA-Z0-9_]*$', s):
            tokens.append(('NAME', s))
        elif re.match(r'^[+\-*/<>=(),]$', s):
            tokens.append(('OP', s))
        else:
            raise ValueError(f'Invalid token: {s}')
    return tokens
