def simulate_lru(capacity: int, operations: list[tuple]) -> tuple[list, list]:
    if capacity == 0:
        return [], []

    cache = {}
    keys = []
    results = []

    for op in operations:
        if op[0] == "put":
            key, value = op[1], op[2]
            if key in cache:
                cache[key][1] = len(keys)
            else:
                if len(keys) == capacity:
                    del cache[keys[0]]
                    keys.pop(0)
                cache[key] = [value, len(keys)]
            keys.append(key)
        elif op[0] == "get":
            key = op[1]
            if key in cache:
                results.append(cache[key][0])
                keys.pop(cache[key][1])
                keys.append(key)
            else:
                results.append(None)

    return results, keys
