import heapq

def cheapest_route(edges: list[tuple[str, str, int]], start: str, goal: str) -> tuple[int, list[str]] | None:
    graph = {}
    for u, v, w in edges:
        if u not in graph:
            graph[u] = {}
        if v not in graph:
            graph[v] = {}
        graph[u][v] = w
        graph[v][u] = w

    queue = [(0, start, [start])]
    visited = {start: 0}

    while queue:
        (cost, node, path) = heapq.heappop(queue)
        if node not in visited or cost < visited[node]:
            visited[node] = cost
            if node == goal:
                return cost, path
            for neighbor, neighbor_cost in graph[node].items():
                if neighbor not in visited or cost + neighbor_cost < visited[neighbor]:
                    visited[neighbor] = cost + neighbor_cost
                    heapq.heappush(queue, (cost + neighbor_cost, neighbor, path + [neighbor]))

    return None
```

