def is_allowed_webhook(url: str) -> bool:
    if not url.startswith('https://'):
        return False
    if '@' in url:
        return False
    if ':' in url:
        user_info, url = url.split(':', 1)
        if '//' in user_info:
            return False
        url = ':' + url
    if '.' in url:
        url = url.split('.')
