        if not re.match(r'^[a-z0-9-]*$', host):
            return False
        if not re.match(r'^\d+$', port):
            return False
        if port not in ['80', '443']:
            return False
    else:
        return False
    if url.endswith('.localhost') or url == 'localhost':
        return False
    return True
