import re

def is_allowed_webhook(url: str) -> bool:
    if not url.startswith('https://'):
        return False
    if '@' in url:
        return False
    if ':' in url:
        user_info, url = url.split(':', 1)
        if '//' in user_info:
            return False
        if '@' in user_info:
            return False
        url = ':' + url
    if '.' in url and url[-1] == '.':
        url = url[:-1]
    url = url.split('/')[2]
    if ':' in url:
        host, port = url.split(':')
        if not re.match(r'^[a-zA-Z0-9-]*$', host):
            return False
        if not re.match(r'^\d+$', port):
            return False
        if int(port) < 1024 or int(port) > 65535:
            return False
    else:
        if not re.match(r'^[a-zA-Z0-9-]*$', url):
            return False
        url = url + ':443'
    if url.lower().endswith('.localhost') or url == 'localhost':
        return False
    return True
