import re

def is_allowed_webhook(url: str) -> bool:
    # Check if url starts with https://
    if not url.startswith('https://'):
        return False

    # Check if url contains any backslash, space or control character
    if any(c in url for c in '\\/"'):
        return False

    # Check if url contains any uppercase letter
    if any(c.isupper() for c in url):
        return False

    # Check if url contains any special character
    if not re.match('^[-a-zA-Z0-9@:%._\+~#=]{2,256}\.[a-z]{2,6}\b([-a-zA-Z0-9@:%_\+.~#?&//=]*)$', url):
        return False

    # Check if host is localhost or .localhost
    host = url.split('/')[2].split(':')[0]
    if host in ['localhost', '.localhost']:
        return False

    # Check if port is 443
    port = url.split('/')[2].split(':')[1] if ':' in url.split('/')[2] else None
    if port and port != '443':
        return False

    return True

