    def divide(a, b):
        return a // b if a >= 0 and b > 0 else -((-a) // b)

    def precedence(op):
        if op == '+' or op == '-':
            return 1
        if op == '*' or op == '/' or op == '//':
            return 2
        if op == '^':
            return 3
        return 0

    def apply_operator(operators, values):
        op = operators[-1]
        operators.pop()
        right = values[-1]
        values.pop()
        left = values[-1]
        values.pop()
        if op == '+':
            values.append(left + right)
        elif op == '-':
            values.append(left - right)
        elif op == '*':
            values.append(left * right)
        elif op == '/':
            values.append(divide(left, right))
        elif op == '//':
            values.append(divide(left, right))
        elif op == '^':
            values.append(left ** right)

    def greater_precedence(op1, op2):
        return precedence(op1) > precedence(op2)

    operators = []
    values = []
    number = 0
    for ch in expr:
        if ch == ' ':
