def evaluate_expression(expr: str) -> int:
    op_map = {
        '+': operator.add,
        '-': operator.sub,
        '*': operator.mul,
        '/': operator.floordiv,
        '^': operator.pow,
    }
    tokens = []
    token = ''
    for c in expr:
        if c in op_map or c in "()":
            if token:
                tokens.append(int(token))
                token = ''
            tokens.append(c)
        else:
            token += c
    if token:
        tokens.append(int(token))

    def evaluate(tokens):
        stack = []
        for token in tokens:
            if token in op_map:
                right = stack.pop()
                left = stack.pop()
                stack.append(op_map[token](left, right))
            else:
                stack.append(token)
        return stack[0]

    def find_matching_parenthesis(tokens):
        count = 0
        for i, token in enumerate(tokens):
            if token == '(':
                count += 1
            elif token == ')':
                count -= 1
                if count == 0:
                    return i
        return -1

    while '(' in tokens:
        end_index = find_matching_parenthesis(tokens)
        sub_expr = tokens[1:end_index]
        sub_expr_value = evaluate(sub_expr)
        tokens = tokens[:1] + [sub_expr_value] + tokens[end_index+1:]

    return evaluate(tokens)
