import operator
import re

OPERATORS = {
    '+': (operator.add, 1),
    '-': (operator.sub, 1),
    '*': (operator.mul, 2),
    '/': (operator.floordiv, 2),
    '^': (operator.pow, 3),
}

def evaluate_expression(expr: str) -> int:
    def parse_atom(s: str) -> int:
        if s.isdigit():
            return int(s)
        else:
            raise ValueError(f"Invalid atom: {s}")

    def parse_factor(s: str) -> int:
        if s.startswith('-'):
            return -parse_atom(s[1:])
        else:
            return parse_atom(s)

    def parse_term(s: str) -> int:
        accumulator = parse_factor(s)
        while True:
            for op, (func, precedence) in OPERATORS.items():
                match = re.match(f"^({op})", s)
                if match:
                    s = s[match.end():]
                    argument = parse_factor(s)
                    accumulator = func(accumulator, argument)
                    break
            else:
                return accumulator

    def parse_expr(s: str) -> int:
        s = re.sub(r"\s+", "", s)
        s = re.sub(r"(-+)", lambda m: "-" * len(m.group(1)), s)
        s = re.sub(r"(\d+)\(", r"\1*(", s)
        return parse_term(s)

    return parse_expr(expr)
