def rotate_rings(matrix: list[list[int]], k: int) -> list[list[int]]:
    if not matrix:
        return []

    n = len(matrix)
    m = len(matrix[0])
    new_matrix = [[0]*m for _ in range(n)]

    for i in range(min(n, m) // 2):
        ring_size = 2 * (n - 2 * i) + 2 * (m - 2 * i) - 4
        rotate_by = k % ring_size

        for j in range(i, m - i):
            new_matrix[i][j] = matrix[i][(j - rotate_by) % m]

        for j in range(i + 1, n - i):
            new_matrix[j][m - i - 1] = matrix[(j - rotate_by) % n][m - i - 1]

        for j in range(i + 1, m - i):
            new_matrix[n - i - 1][m - j - 1] = matrix[n - i - 1][(m - j - rotate_by) % m]

        for j in range(i + 1, n - i - 1):
            new_matrix[n - j - 1][i] = matrix[(n - j - rotate_by) % n][i]

    if n * m % 2 == 1:
        new_matrix[n // 2][m // 2] = matrix[n // 2][m // 2]

    return new_matrix

