def render_report_header(template: str, report: dict) -> str:
    env = Environment(autoescape=select_autoescape(['html', 'xml']))
    template = env.from_string(template)

    # Replace placeholders with values from report
    for key, value in report.items():
        # Convert all non-string values to string
        if not isinstance(value, str):
            report[key] = str(value)

    # Replace empty strings with placeholders
    for key, value in report.items():
        if value == '':
            report[key] = '{{ ' + key + ' }}'

    # Render the template
    rendered_template = template.render(report=report)

    # Add conditional block for draft status
    if 'draft' in report and report['draft']:
        rendered_template = rendered_template.replace('{% if report.draft %}', '{% if ' + key + ' %}').replace('{% endif %}', '{% endif %}')
    else:
        rendered_template = rendered_template.replace('{% if report.draft %}', '').replace('{% endif %}', '')

    return rendered_template
