            close_paren_tokens = []
            while tokens:
                token = tokens.pop()
                if token == '(':
                    break
                close_paren_tokens.append(token)
            tokens.append(evaluate_expression(close_paren_tokens))

    if current_number:
        tokens.append(int(current_number))

    while len(tokens) > 1:
        try:
            operator_index = tokens.index('^')
