def run_stack_machine(program: list[str]) -> list[int]:
    stack = []
    pc = 0  # Program Counter
    while pc < len(program):
        instruction = program[pc]
        pc += 1
        if instruction == 'HALT':
            break
        elif instruction == 'PUSH':
            if len(stack) == 1000:
                raise RuntimeError('Stack overflow')
            if pc >= len(program):
                raise ValueError('Missing argument for PUSH')
            n = int(program[pc])
            pc += 1
            stack.append(n)
        elif instruction == 'POP':
            if not stack:
                raise ValueError('Stack is empty')
            stack.pop()
        elif instruction == 'DUP':
            if len(stack) < 1:
                raise ValueError('Stack has less than 1 element')
            stack.append(stack[-1])
        elif instruction == 'SWAP':
            if len(stack) < 2:
                raise ValueError('Stack has less than 2 elements')
            stack[-1], stack[-2] = stack[-2], stack[-1]
        elif instruction == 'ADD':
            if len(stack) < 2:
                raise ValueError('Stack has less than 2 elements')
            stack.append(stack.pop() + stack.pop())
        elif instruction == 'SUB':
            if len(stack) < 2:
                raise ValueError('Stack has less than 2 elements')
            a = stack.pop()
            b = stack.pop()
            stack.append(b - a)
        elif instruction == 'MUL':
            if len(stack) < 2:
                raise ValueError('Stack has less than 2 elements')
            stack.append(stack.pop() * stack.pop())
        elif instruction.startswith('JMP'):
            pc = int(instruction.split()[1])
        elif instruction.startswith('JZ'):
            if not stack[-1]:
                pc = int(instruction.split()[1])
            else:
                stack.pop()
        else:
            raise ValueError(f'Unknown instruction: {instruction}')
    return stack
