def run_stack_machine(program: list[str]) -> list[int]:
    stack = []
    pc = 0  # Program Counter
    labels = {}

    # First pass to build the labels dictionary
    for i, instruction in enumerate(program):
        if instruction.startswith('JMP') or instruction.startswith('JZ'):
            label = instruction.split()[1]
            if label in labels:
                raise ValueError(f"Duplicate label '{label}'")
            labels[label] = i

    while pc < len(program):
        instruction = program[pc]
        pc += 1

        if instruction == 'HALT':
            break
        elif instruction == 'POP':
            if not stack:
                raise ValueError("Empty stack")
            stack.pop()
        elif instruction.startswith('PUSH'):
            n = int(instruction.split()[1])
            stack.append(n)
        elif instruction == 'DUP':
            if not stack:
                raise ValueError("Empty stack")
            stack.append(stack[-1])
        elif instruction == 'SWAP':
            if len(stack) < 2:
                raise ValueError("Not enough elements on the stack")
            stack[-1], stack[-2] = stack[-2], stack[-1]
        elif instruction == 'ADD':
            if len(stack) < 2:
                raise ValueError("Not enough elements on the stack")
            stack.append(stack.pop() + stack.pop())
        elif instruction == 'SUB':
            if len(stack) < 2:
                raise ValueError("Not enough elements on the stack")
            a = stack.pop()
            b = stack.pop()
            stack.append(b - a)
        elif instruction == 'MUL':
            if len(stack) < 2:
                raise ValueError("Not enough elements on the stack")
            stack.append(stack.pop() * stack.pop())
        elif instruction.startswith('JMP'):
            label = instruction.split()[1]
            if label not in labels:
                raise ValueError(f"Unknown label '{label}'")
            pc = labels[label]
        elif instruction.startswith('JZ'):
            label = instruction.split()[1]
            if label not in labels:
                raise ValueError(f"Unknown label '{label}'")
            if not stack or stack[-1] != 0:
                pc -= 1  # Do not increment the program counter
            else:
                pc = labels[label]
        else:
            raise ValueError(f"Unknown instruction '{instruction}'")

        if len(stack) > 1000:
            raise RuntimeError("Stack overflow")

    return stack
