import re

def is_allowed_webhook(url: str) -> bool:
    # Check if url starts with 'https://'
    if not url.lower().startswith('https://'):
        return False

    # Check if url contains any backslash, space, control character
    if any(c in url for c in map(chr, range(32, 128))):
        return False

    # Check if url contains any non-ASCII letter, digit or '-'
    if not re.match(r'^[-a-zA-Z0-9-]+$', url.split('/')[2].split(':')[0]):
        return False

    # Check if url contains 'localhost' or '.localhost'
    if 'localhost' in url.lower():
        return False

    # Check if url contains port other than 443
    if ':' in url and not url.rsplit(':', 1)[-1] == '443':
        return False

    return True
