import operator
import math

def evaluate_expression(expr: str) -> int:
    op_map = {
        '+': operator.add,
        '-': operator.sub,
        '*': operator.mul,
        '/': operator.floordiv,
        '^': operator.pow,
    }

    tokens = expr.split()
    stack = []

    for token in tokens:
        if token in op_map:
            b = stack.pop()
            a = stack.pop()
            stack.append(op_map[token](a, b))
        elif token == '(':
            continue
        elif token == ')':
            b = stack.pop()
            op = stack.pop()
            a = stack.pop()
            stack.append(op_map[op](a, b))
        elif token == '-':
            if not stack or type(stack[-1]) == str:
                stack.append(token)
            else:
                b = stack.pop()
                a = stack.pop()
                stack.append(op_map['-'](a, b))
        else:
            stack.append(int(token))

    return stack[0]
