def process_orders(events: list[tuple[str, str, int]]) -> tuple[dict[str, int], list[tuple[str, int]]]:
    stock = {}
    waiting = []
    for event in events:
        kind, item, quantity = event
        if kind == 'receive':
            if item in stock:
                stock[item] += quantity
            else:
                stock[item] = quantity
        elif kind == 'order':
            if item in stock and stock[item] >= quantity:
                stock[item] -= quantity
                if stock[item] == 0:
                    del stock[item]
            else:
                waiting.append(event)
    return stock, waiting
