def evaluate_expression(expr: str) -> int:
    op_map = {
        '+': operator.add,
        '-': operator.sub,
        '*': operator.mul,
        '/': operator.floordiv,
        '^': operator.pow,
    }

    def parse_expr(expr):
        nums = []
        ops = []
        num = ''
        for ch in expr:
            if ch.isdigit():
                num += ch
            else:
                if num:
                    nums.append(int(num))
                    num = ''
                if ch in op_map:
                    while ops and ops[-1] in op_map and op_map[ch].priority <= op_map[ops[-1]].priority:
                        nums.append(ops.pop())
                    ops.append(ch)
                elif ch == '(':
                    ops.append(ch)
                elif ch == ')':
                    while ops[-1] != '(':
                        nums.append(ops.pop())
                    ops.pop()
        if num:
            nums.append(int(num))
        while ops:
            nums.append(ops.pop())
        return nums

    stack = parse_expr(expr.replace(' ', ''))
    for token in stack:
        if token in op_map:
            b = stack.pop()
            a = stack.pop()
            stack.append(op_map[token](a, b))
        else:
            stack.append(token)
    return stack[0]
