    stock = {}
    waiting = []
    waiting_orders = {}

    for event in events:
        kind, item, quantity = event

        if item not in stock:
            stock[item] = 0

        if kind == 'receive':
            stock[item] += quantity

            if item in waiting_orders:
                while stock[item] > 0 and waiting_orders[item]:
                    order_quantity = waiting_orders[item].pop(0)
                    if order_quantity <= stock[item]:
                        stock[item] -= order_quantity
                    else:
                        waiting_orders[item].append(order_quantity - stock[item])
                        stock[item] = 0
                        break

        elif kind == 'order':
            if stock[item] >= quantity:
                stock[item] -= quantity
            else:
                waiting.append((item, quantity))
                waiting_orders[item] = waiting_orders.get(item, []) + [quantity]

    return (stock, waiting)
