    stock = {}
    waiting = []
    waiting_orders = {}

    for event in events:
        kind, item, quantity = event

        if item not in stock:
            stock[item] = 0

        if kind == 'receive':
            stock[item] += quantity

            # Ship waiting orders
            while waiting_orders.get(item, 0) > 0 and stock[item] >= waiting_orders[item]:
                stock[item] -= waiting_orders[item]
                waiting_orders[item] = 0
                waiting.pop(0)

        elif kind == 'order':
            waiting_orders[item] = waiting_orders.get(item, 0) + quantity

            # If stock is enough, ship immediately
            if stock[item] >= quantity:
                stock[item] -= quantity

                if stock[item] == 0:
                    del stock[item]

                # Remove fulfilled orders
                while waiting_orders[item] > 0 and stock.get(item, 0) >= waiting_orders[item]:
                    stock[item] -= waiting_orders[item]
                    waiting_orders[item] = 0
                    waiting.pop(0)

            # If stock is not enough, add to waiting list
            else:
                waiting.append((item, quantity))

    # Add remaining waiting orders to stock
    for item, quantity in waiting_orders.items():
        if item in stock:
            stock[item] += quantity
        else:
            stock[item] = quantity

    return stock, list(waiting)
