def run_stack_program(program: list[str]) -> list[int] | None:
    stack = []
    pc = 0  # Program counter
    max_instructions = 1000
    while pc < len(program) and max_instructions > 0:
        max_instructions -= 1
        instruction = program[pc]
        op, *args = instruction.split()
        if op == 'PUSH':
            stack.append(int(args[0]))
        elif op == 'POP':
            if not stack:
                return None
            stack.pop()
        elif op == 'DUP':
            if len(stack) < 1:
                return None
            stack.append(stack[-1])
        elif op == 'SWAP':
            if len(stack) < 2:
                return None
            stack[-1], stack[-2] = stack[-2], stack[-1]
        elif op == 'ADD':
            if len(stack) < 2:
                return None
            stack.append(stack.pop() + stack.pop())
        elif op == 'SUB':
            if len(stack) < 2:
                return None
            a, b = stack.pop(), stack.pop()
            stack.append(b - a)
        elif op == 'MUL':
            if len(stack) < 2:
                return None
            stack.append(stack.pop() * stack.pop())
        elif op == 'JMP':
            pc = int(args[0]) - 1
        elif op == 'JZ':
            if not stack:
                return None
            if stack.pop() == 0:
                pc = int(args[0]) - 1
        else:
            return None
        pc += 1
    return stack if max_instructions > 0 else None
