            if len(stack) < 2:
                return None
            stack[-2] = stack[-2] + stack[-1]
            stack.pop()

        elif instruction == "SUB":
            if len(stack) < 2:
                return None
            stack[-2] = stack[-2] - stack[-1]
            stack.pop()

        elif instruction == "MUL":
            if len(stack) < 2:
                return None
            stack[-2] = stack[-2] * stack[-1]
            stack.pop()

        elif instruction.startswith("PUSH"):
            try:
                stack.append(int(instruction.split()[1]))
            except (IndexError, ValueError):
                return None

        elif instruction.startswith("JMP"):
