def run_stack_machine(program: list[str]) -> list[int]:
    stack = []
    ip = 0
    max_instructions = 1000
    while ip < len(program) and ip < max_instructions:
        instruction = program[ip].split()
        op = instruction[0]
        if op == 'PUSH':
            if len(instruction) != 2 or not instruction[1].isdigit():
                raise ValueError('Invalid PUSH instruction')
            stack.append(int(instruction[1]))
        elif op == 'POP':
            if not stack:
                raise ValueError('Empty stack')
            stack.pop()
        elif op == 'DUP':
            if not stack:
                raise ValueError('Empty stack')
            stack.append(stack[-1])
        elif op == 'SWAP':
            if len(stack) < 2:
                raise ValueError('Not enough elements in stack')
            stack[-1], stack[-2] = stack[-2], stack[-1]
        elif op == 'ADD':
            if len(stack) < 2:
                raise ValueError('Not enough elements in stack')
            a = stack.pop()
            b = stack.pop()
            stack.append(a + b)
        elif op == 'SUB':
            if len(stack) < 2:
                raise ValueError('Not enough elements in stack')
            a = stack.pop()
            b = stack.pop()
            stack.append(a - b)
        elif op == 'MUL':
            if len(stack) < 2:
                raise ValueError('Not enough elements in stack')
            a = stack.pop()
            b = stack.pop()
            stack.append(a * b)
        elif op == 'JMP':
            if len(instruction) != 2 or not instruction[1].isdigit():
                raise ValueError('Invalid JMP instruction')
            ip = int(instruction[1]) - 1
        elif op == 'JZ':
            if len(instruction) != 2 or not instruction[1].isdigit():
                raise ValueError('Invalid JZ instruction')
            if not stack:
                raise ValueError('Empty stack')
            if stack[-1] == 0:
                ip = int(instruction[1]) - 1
            else:
                stack.pop()
        elif op == 'HALT':
            break
        else:
            raise ValueError('Invalid instruction')
        ip += 1
    if ip == len(program):
        return stack
    else:
        raise RuntimeError('Maximum instructions executed')
