def is_allowed_webhook(url: str) -> bool:
    # Comprueba si comienza con https://
    if not url.lower().startswith('https://'):
        return False

    # Comprueba si no contiene ninguna barra invertida, espacio ni carácter de control
    if any(c in url for c in ['\\', ' ', '\t', '\n', '\r', '\f', '\v']):
        return False

    # Extrae el host de la URL
    host = url.split('/')[2].split(':')[0].split('@')[-1]

    # Comprueba si el host no es localhost y no termina en .localhost
    if host.lower() in ['localhost', 'localhost.']:
        return False

    # Comprueba si el host tiene dos o más etiquetas separadas por .
    labels = host.split('.')
    if len(labels) < 2:
        return False

    # Comprueba si cada etiqueta no está vacía y consta solo de letras ASCII, dígitos y -
    if not all(re.match(r'^[a-z0-9-]+$', label) for label in labels):
        return False

    # Comprueba si la �ltima etiqueta consta solo de letras
    if not re.match(r'^[a-z]+$', labels[-1]):
        return False

    # Comprueba si el puerto está ausente o es 443
    if ':' in url:
        port = url.split(':')[2].split('/')[0]
        if port not in ['', '443']:
            return False

    return True

