def run_stack_machine(program: list[str]) -> list[int]:
    stack = []
    pc = 0  # Program Counter
    max_instructions = 1000

    while pc < len(program) and max_instructions > 0:
        max_instructions -= 1
        instruction = program[pc].split()
        opcode = instruction[0]

        if opcode == 'PUSH':
            stack.append(int(instruction[1]))
        elif opcode == 'POP':
            if not stack:
                raise ValueError('POP: stack is empty')
            stack.pop()
        elif opcode == 'DUP':
            if not stack:
                raise ValueError('DUP: stack is empty')
            stack.append(stack[-1])
        elif opcode == 'SWAP':
            if len(stack) < 2:
                raise ValueError('SWAP: stack has less than 2 elements')
            stack[-1], stack[-2] = stack[-2], stack[-1]
        elif opcode == 'ADD':
            if len(stack) < 2:
                raise ValueError('ADD: stack has less than 2 elements')
            stack.append(stack.pop() + stack.pop())
        elif opcode == 'SUB':
            if len(stack) < 2:
                raise ValueError('SUB: stack has less than 2 elements')
            a = stack.pop()
            b = stack.pop()
            stack.append(b - a)
        elif opcode == 'MUL':
            if len(stack) < 2:
                raise ValueError('MUL: stack has less than 2 elements')
            stack.append(stack.pop() * stack.pop())
        elif opcode == 'JMP':
            if len(instruction) != 2 or not instruction[1].isdigit() or int(instruction[1]) >= len(program):
                raise ValueError('JMP: invalid argument')
            pc = int(instruction[1])
            continue
        elif opcode == 'JZ':
            if not stack:
                raise ValueError('JZ: stack is empty')
            if stack[-1] == 0:
                if len(instruction) != 2 or not instruction[1].isdigit() or int(instruction[1]) >= len(program):
                    raise ValueError('JZ: invalid argument')
                pc = int(instruction[1])
                continue
            stack.pop()
        elif opcode == 'HALT':
            break
        else:
            raise ValueError(f'Unknown opcode: {opcode}')

        pc += 1

    if max_instructions <= 0:
        raise RuntimeError('Too many instructions executed')

    return stack
