from collections import deque, defaultdict

def process_orders(events: list[tuple[str, str, int]]) -> tuple[dict[str, int], list[tuple[str, int]]]:
    stock = defaultdict(int)
    waiting = defaultdict(deque)
    waiting_orders = []

    for event in events:
        kind, item, quantity = event

        if kind == 'receive':
            stock[item] += quantity
            # Check if there are waiting orders for this item
            while waiting[item] and stock[item]:
                waiting_order = waiting[item].popleft()
                if waiting_order[1] <= stock[item]:
                    stock[item] -= waiting_order[1]
                    waiting_orders.append(waiting_order)
                else:
                    waiting[item].appendleft((waiting_order[0], waiting_order[1] - stock[item]))
                    stock[item] = 0
                    break
        elif kind == 'order':
            if stock[item] >= quantity:
                stock[item] -= quantity
                waiting_orders.append((item, quantity))
            else:
                waiting[item].append((item, quantity - stock[item]))
                stock[item] = 0

    # Remove items with zero stock
    stock = {item: quantity for item, quantity in stock.items() if quantity > 0}

    return (stock, waiting_orders)
