    max_instructions = 1000
    while pc < len(program) and pc < max_instructions:
        instruction = program[pc].split()
        opcode = instruction[0]
        if opcode == 'PUSH':
            try:
                value = int(instruction[1])
                stack.append(value)
            except (IndexError, ValueError):
                raise ValueError('Invalid PUSH instruction')
        elif opcode == 'POP':
            if not stack:
                raise ValueError('Empty stack')
            stack.pop()
        elif opcode == 'DUP':
            if not stack:
                raise ValueError('Empty stack')
            stack.append(stack[-1])
        elif opcode == 'SWAP':
            if len(stack) < 2:
                raise ValueError('Not enough items on stack for SWAP')
            stack[-1], stack[-2] = stack[-2], stack[-1]
        elif opcode == 'ADD':
            if len(stack) < 2:
                raise ValueError('Not enough items on stack for ADD')
            stack.append(stack.pop() + stack.pop())
        elif opcode == 'SUB':
            if len(stack) < 2:
                raise ValueError('Not enough items on stack for SUB')
            a = stack.pop()
            b = stack.pop()
            stack.append(b - a)
        elif opcode == 'MUL':
            if len(stack) < 2:
                raise ValueError('Not enough items on stack for MUL')
            stack.append(stack.pop() * stack.pop())
        elif opcode == 'JMP':
            try:
                target = int(instruction[1])
                if target < 0 or target >= len(program):
                    raise ValueError('Invalid JMP target')
                pc = target
                continue
            except (IndexError, ValueError):
                raise ValueError('Invalid JMP instruction')
        elif opcode == 'JZ':
            try:
                target = int(instruction[1])
                if not stack:
                    raise ValueError('Empty stack')
