            except (IndexError, ValueError):
                raise ValueError('Invalid JZ instruction')
        elif opcode == 'HALT':
            break
        else:
            raise ValueError('Invalid opcode')
        pc += 1
    if pc == max_instructions:
        raise RuntimeError('Maximum instructions executed')
    return stack
