def process_orders(events: list[tuple[str, str, int]]) -> tuple[dict[str, int], list[tuple[str, int]]]:
    stock = {}
    waiting = {}
    order_queue = {}

    for event in events:
        kind, item, quantity = event

        if kind == 'receive':
            if item in stock:
                stock[item] += quantity
            else:
                stock[item] = quantity

            # Process waiting orders
            if item in waiting:
                while quantity > 0 and waiting[item] > 0:
                    waiting[item] -= 1
                    quantity -= 1

                if waiting[item] == 0:
                    del waiting[item]

        elif kind == 'order':
            if item in stock and stock[item] >= quantity:
                # Enough stock to fulfill the order
                stock[item] -= quantity

            else:
                # Not enough stock, add to the waiting list
                if item in waiting:
                    waiting[item] += quantity
                else:
                    waiting[item] = quantity

                # Add to the order queue
                if item in order_queue:
                    order_queue[item].append((kind, quantity))
                else:
                    order_queue[item] = [(kind, quantity)]

    # Remaining orders in the order queue
    for item, orders in order_queue.items():
        for kind, quantity in orders:
            if item in stock and stock[item] >= quantity:
                stock[item] -= quantity

    return (stock, list(waiting.items()))
