def process_orders(events: list[tuple[str, str, int]]) -> tuple[dict[str, int], list[tuple[str, int]]]:
    stock = {}
    waiting = {}
    waiting_queue = []

    for event in events:
        kind, item, quantity = event

        if kind == 'receive':
            if item in stock:
                stock[item] += quantity
            else:
                stock[item] = quantity

            # Ship waiting orders
            while waiting.get(item, 0) > 0 and stock[item] >= quantity:
                stock[item] -= quantity
                waiting[item] -= quantity
                if waiting[item] == 0:
                    del waiting[item]

        elif kind == 'order':
            if item in stock and stock[item] >= quantity:
                # Item in stock, ship immediately
                stock[item] -= quantity
                if stock[item] == 0:
                    del stock[item]
            else:
                # Item not in stock, add to waiting queue
                waiting_queue.append((item, quantity))
                waiting[item] = waiting.get(item, 0) + quantity

    # Sort waiting queue by order placement order
    waiting_queue.sort(key=lambda x: events.index(('order', x[0], x[1])))

    return stock, waiting_queue
