def run_bank_ops(balances: dict[str, int], ops: list[tuple]) -> tuple[dict[str, int], list[int]]:
    frozen = set()
    failed = []
    final_balances = balances.copy()

    for i, op in enumerate(ops):
        op_type, *args = op

        if op_type == 'deposit':
            account, amount = args
            if account in frozen:
                failed.append(i)
            elif amount <= 0 or account not in final_balances:
                failed.append(i)
            else:
                final_balances[account] += amount

        elif op_type == 'withdraw':
            account, amount = args
            if account in frozen:
                failed.append(i)
            elif amount <= 0 or account not in final_balances or final_balances[account] < amount:
                failed.append(i)
            else:
                final_balances[account] -= amount

        elif op_type == 'transfer':
            source, target, amount = args
            if source in frozen or target in frozen or amount <= 0 or source not in final_balances or target not in final_balances or final_balances[source] < amount:
                failed.append(i)
            else:
                final_balances[source] -= amount
                final_balances[target] += amount

        elif op_type == 'freeze':
            account = args[0]
            if account not in final_balances:
                failed.append(i)
            else:
                frozen.add(account)

        elif op_type == 'unfreeze':
            account = args[0]
            if account not in frozen:
                failed.append(i)
            else:
                frozen.remove(account)

        else:
            failed.append(i)

    return final_balances, failed
