        elif opcode == "ADD":
            if len(stack) < 2:
                raise ValueError("ADD: stack has less than 2 elements")
            stack.append(stack.pop() + stack.pop())
        elif opcode == "SUB":
            if len(stack) < 2:
                raise ValueError("SUB: stack has less than 2 elements")
            a = stack.pop()
            b = stack.pop()
            stack.append(b - a)
        elif opcode == "MUL":
            if len(stack) < 2:
                raise ValueError("MUL: stack has less than 2 elements")
            stack.append(stack.pop() * stack.pop())
