def run_bank_ops(balances: dict[str, int], ops: list[tuple]) -> tuple[dict[str, int], list[int]]:
    frozen = set()
    failed = []
    for i, op in enumerate(ops):
        op_type, *args = op
        if op_type == 'deposit':
            account, amount = args
            if account not in balances or amount <= 0 or account in frozen:
                failed.append(i)
            else:
                balances[account] += amount
        elif op_type == 'withdraw':
            account, amount = args
            if account not in balances or amount <= 0 or account in frozen or balances[account] - amount < 0:
                failed.append(i)
            else:
                balances[account] -= amount
        elif op_type == 'transfer':
            source, target, amount = args
            if source not in balances or target not in balances or amount <= 0 or source == target or source in frozen or target in frozen or balances[source] - amount - 2 < 0:
                failed.append(i)
            else:
                balances[source] -= amount + 2
                balances[target] += amount
        elif op_type == 'freeze':
            account = args[0]
            if account not in balances or account in frozen:
                failed.append(i)
            else:
                frozen.add(account)
        elif op_type == 'unfreeze':
            account = args[0]
            if account not in balances or account not in frozen:
                failed.append(i)
            else:
                frozen.remove(account)
        else:
            failed.append(i)
    return balances, failed
