def run_stack_program(program: list[str]) -> list[int] | None:
    stack = []
    pc = 0  # Program counter
    max_instructions = 1000

    while pc < len(program) and max_instructions > 0:
        max_instructions -= 1
        instruction = program[pc]

        if instruction.startswith('PUSH'):
            stack.append(int(instruction.split()[1]))
        elif instruction == 'POP':
            if not stack:
                return None
            stack.pop()
        elif instruction == 'DUP':
            if len(stack) < 1:
                return None
            stack.append(stack[-1])
        elif instruction == 'SWAP':
            if len(stack) < 2:
                return None
            stack[-1], stack[-2] = stack[-2], stack[-1]
        elif instruction == 'ADD':
            if len(stack) < 2:
                return None
            stack.append(stack.pop() + stack.pop())
        elif instruction == 'SUB':
            if len(stack) < 2:
                return None
            a = stack.pop()
            b = stack.pop()
            stack.append(b - a)
        elif instruction == 'MUL':
            if len(stack) < 2:
                return None
            stack.append(stack.pop() * stack.pop())
        elif instruction.startswith('JMP'):
            pc = int(instruction.split()[1])
            continue
        elif instruction.startswith('JZ'):
            if not stack:
                return None
            if stack[-1] == 0:
                pc = int(instruction.split()[1])
                continue
        pc += 1

    return stack if max_instructions > 0 else None
