def is_monotonic(nums: list[int]) -> bool:
    if len(nums) <= 1:
        return True
    increasing = None
    for i in range(len(nums) - 1):
        if nums[i] == nums[i + 1]:
            continue
        elif nums[i] < nums[i + 1]:
            if increasing is not None and not increasing:
                return False
            increasing = True
        else:
            if increasing is not None and increasing:
                return False
            increasing = False
    return True
