def process_orders(events: list[tuple[str, str, int]]) -> tuple[dict[str, int], list[tuple[str, int]]]:
    stock = {}
    waiting = []
    waiting_orders = {}

    for event in events:
        kind, item, quantity = event

        if kind == 'receive':
            if item in stock:
                stock[item] += quantity
            else:
                stock[item] = quantity

            # Send waiting orders
            while waiting_orders.get(item, 0) > 0 and stock.get(item, 0) >= quantity:
                waiting_orders[item] -= quantity
                stock[item] -= quantity
                if waiting_orders[item] == 0:
                    del waiting_orders[item]

        elif kind == 'order':
            if item in stock and stock[item] >= quantity:
                stock[item] -= quantity
                if stock[item] == 0:
                    del stock[item]
            else:
                waiting.append((item, quantity))
                if item in waiting_orders:
                    waiting_orders[item] += quantity
                else:
                    waiting_orders[item] = quantity

    # Add remaining stock to the result
    for item, quantity in stock.items():
        if quantity > 0:
            waiting_orders[item] = quantity

    # Sort waiting orders by the order of arrival
    waiting = sorted(waiting, key=lambda x: waiting.index(x))

    return stock, waiting
