    stock = {}
    waiting = []
    waiting_orders = {}
    for event in events:
        kind, item, quantity = event
        if kind == 'receive':
            if item in stock:
                stock[item] += quantity
            else:
                stock[item] = quantity
            while waiting_orders.get(item) is not None and stock.get(item, 0) >= waiting_orders[item][1]:
                stock[item] -= waiting_orders[item][1]
                waiting.append((item, waiting_orders[item][1]))
                del waiting_orders[item]
        elif kind == 'order':
            if stock.get(item, 0) >= quantity:
                stock[item] -= quantity
            else:
                waiting_orders[item] = (len(waiting), quantity)
    return (stock, sorted(waiting, key=lambda x: x[1]))

