def count_queens(n: int, blocked: list[tuple[int, int]]) -> int:
    # Create a blocked set for faster lookup
    blocked_set = set(blocked)

    # Define a helper function to check if a queen can be placed at a certain position
    def can_place(row, col):
        # Check if the square is blocked
        if (row, col) in blocked_set:
            return False
        # Check if there is a queen in the same row or column
        for i in range(n):
            if (row, i) in blocked_set or (i, col) in blocked_set:
                return False
        # Check if there is a queen in the diagonal
        for i in range(n):
            if (row - i, col - i) in blocked_set or (row - i, col + i) in blocked_set or \
               (row + i, col - i) in blocked_set or (row + i, col + i) in blocked_set:
                return False
        return True

    # Define a recursive function to count the number of ways to place queens
    def count_ways(row):
        # Base case: if all queens are placed, return 1
        if row == n:
            return 1
        # Recursive case: try to place a queen in the current row and count the number of ways to place the rest of the queens
        count = 0
        for col in range(n):
            if can_place(row, col):
                count += count_ways(row + 1)
        return count

    # Start counting from the first row
    return count_ways(0)
