def count_queens(n: int, blocked: list[tuple[int, int]]) -> int:
    if n == 0:
        return 1

    # Create a board of size n x n with all elements set to False
    board = [[False]*n for _ in range(n)]

    # Mark blocked squares as True on the board
    for block in blocked:
        if 0 <= block[0] < n and 0 <= block[1] < n:
            board[block[0]][block[1]] = True

    def is_safe(row, col):
        # Check this row on left side
        for i in range(col):
            if board[row][i]:
                return False

        # Check upper diagonal on left side
        for i, j in zip(range(row, -1, -1), range(col, -1, -1)):
            if board[i][j]:
                return False

        # Check lower diagonal on left side
        for i, j in zip(range(row, n, 1), range(col, -1, -1)):
            if board[i][j]:
                return False

        return True

    def solve(col):
        # base case: If all queens are placed
        if col >= n:
            return 1

        # Consider this column and try placing a queen in all rows one by one
        count = 0
        for i in range(n):
            if is_safe(i, col):
                # Place this queen in board[i][col]
                board[i][col] = True
                # recur to place rest of the queens
                count += solve(col + 1)
                # Remove queen from board[i][col]
                board[i][col] = False

        return count

    return solve(0)
