from collections import deque

def shortest_path_one_break(grid: list[str]) -> int:
    rows, cols = len(grid), len(grid[0])
    start, end = None, None
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 'S':
                start = (i, j)
            elif grid[i][j] == 'E':
                end = (i, j)
    if start is None or end is None:
        return -1

    queue = deque([(start, 0, 0)])  # (position, steps, breaks)
    visited = set([start])
    while queue:
        (x, y), steps, breaks = queue.popleft()
        if (x, y) == end:
            return steps
        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nx, ny = x + dx, y + dy
            if 0 <= nx < rows and 0 <= ny < cols and grid[nx][ny] != '#':
                if (nx, ny) not in visited or (nx, ny) in visited and breaks < 1:
                    if grid[nx][ny] == '#':
                        queue.append(((nx, ny), steps + 1, breaks + 1))
                        visited.add((nx, ny))
                    else:
                        queue.append(((nx, ny), steps + 1, breaks))
                        visited.add((nx, ny))
    return -1
