def weighted_edit_cost(source: str, target: str, insert_cost: int, delete_cost: int, replace_cost: int) -> int:
    if len(source) < len(target):
        source, target = target, source

    if len(target) == 0:
        return len(source) * insert_cost

    previous_row = range(target[0]+1, len(source)+1)
    for s_char, s_index in zip(source, range(1, len(source)+1)):
        current_row = [s_index]
        for t_char, t_index in zip(target, range(1, len(target)+1)):
            insertions = previous_row[t_index] + insert_cost
            deletions = current_row[t_index-1] + delete_cost
            substitutions = previous_row[t_index-1] + (replace_cost if s_char != t_char else 0)
            current_row.append(min(insertions, deletions, substitutions))
        previous_row = current_row

    return previous_row[-1]

