def lex_topological_order(n: int, pairs: list[tuple[int, int]]) -> list[int]:
    if n == 0:
        return []
    graph = [[] for _ in range(n)]
    indegree = [0] * n
    for a, b in pairs:
        if a == b:
            return []
        graph[a].append(b)
        indegree[b] += 1
    zero_indegree = [i for i in range(n) if indegree[i] == 0]
    order = []
    while zero_indegree:
        node = zero_indegree.pop()
        order.append(node)
        for neighbor in graph[node]:
            indegree[neighbor] -= 1
            if indegree[neighbor] == 0:
                zero_indegree.append(neighbor)
    return order if len(order) == n else []

