def solve_congruences(congruences: list[tuple[int, int]]) -> tuple[int, int] | None:
    if not congruences:
        return 0, 1

    x, m = 0, 1
    for r, m_i in congruences:
        g = gcd(m, m_i)
        if (r % m_i - x % m_i) % m_i < 0:
            r += m_i
        x_i = (r // g % m_i * pow(m // g, -1, m_i)) % m_i
        x = x_i * m + r
        m *= m_i // g

    return x % m, m

