def league_table(results: list[tuple[str, str, int, int]]) -> list[tuple[str, int, int, int]]:
    # Initialize an empty dictionary to store team stats
    team_stats = {}

    # Iterate over the results
    for home, away, home_goals, away_goals in results:
        # Update the stats for the home team
        if home not in team_stats:
            team_stats[home] = {'points': 0, 'goals_scored': 0, 'goals_conceded': 0}
        team_stats[home]['points'] += 3 if home_goals > away_goals else (1 if home_goals == away_goals else 0)
        team_stats[home]['goals_scored'] += home_goals
        team_stats[home]['goals_conceded'] += away_goals

        # Update the stats for the away team
        if away not in team_stats:
            team_stats[away] = {'points': 0, 'goals_scored': 0, 'goals_conceded': 0}
        team_stats[away]['points'] += 3 if away_goals > home_goals else (1 if away_goals == home_goals else 0)
        team_stats[away]['goals_scored'] += away_goals
        team_stats[away]['goals_conceded'] += home_goals

    # Convert the stats to a list of tuples and sort it
    league_table = [(team, stats['points'], stats['goals_scored'] - stats['goals_conceded'], stats['goals_scored']) 
                    for team, stats in team_stats.items()]
    league_table.sort(key=lambda x: (-x[1], -x[2], -x[3], x[0]))

    return league_table

