from urllib.parse import urlparse

def fetch_target_allowed(url: str, allowed_hosts: list[str]) -> bool:
    parsed_url = urlparse(url)
    if parsed_url.scheme.lower() not in ['http', 'https']:
        return False
    if parsed_url.netloc.split('.')[-1] == '':
        netloc = parsed_url.netloc.split('.')[:-1]
    else:
        netloc = parsed_url.netloc.split('.')
    netloc = '.'.join(netloc).lower()
    allowed_hosts = [host.lower() for host in allowed_hosts]
    return netloc in allowed_hosts

from urllib.parse import urlparse

def fetch_target_allowed(url: str, allowed_hosts: list[str]) -> bool:
    parsed_url = urlparse(url)
    scheme = parsed_url.scheme.lower()
    host = parsed_url.hostname.lower()

    if scheme not in ['http', 'https']:
        return False

    if '@' in host or ':' in host:
        return False

    if '.' in host:
        host = host.rsplit('.', 1)[1]

    return host in allowed_hosts

