import ast
import operator

def matches_filter(expression: str, record: dict) -> bool:
    # Define the operators
    operators = {ast.Add: operator.add, ast.Sub: operator.sub,
                  ast.Mult: operator.mul, ast.Div: operator.truediv,
                  ast.USub: operator.neg, ast.Pow: operator.pow,
                  ast.BitAnd: operator.and_, ast.BitOr: operator.or_,
                  ast.Lt: operator.lt, ast.LtE: operator.le,
                  ast.Gt: operator.gt, ast.GtE: operator.ge,
                  ast.Eq: operator.eq, ast.NotEq: operator.ne,
                  ast.And: operator.and_, ast.Or: operator.or_,
                  ast.Not: operator.not_}

    # Parse the expression
    try:
        tree = ast.parse(expression, mode='eval').body
    except SyntaxError:
        raise ValueError(f"Invalid expression: {expression}")

    # Check if all variables are in the record
    for node in ast.walk(tree):
        if isinstance(node, ast.Name) and node.id not in record:
            raise ValueError(f"Variable {node.id} not in record")

    # Evaluate the expression
    def _evaluate(node):
        if isinstance(node, ast.Num):
            return node.n
        elif isinstance(node, ast.Name):
            return record[node.id]
        elif isinstance(node, ast.BinOp):
            return operators[type(node.op)](_evaluate(node.left), _evaluate(node.right))
        elif isinstance(node, ast.UnaryOp):
            return operators[type(node.op)](_evaluate(node.operand))
        elif isinstance(node, ast.Compare):
            left = _evaluate(node.left)
            for i, op in enumerate(node.ops):
                right = _evaluate(node.comparators[i])
                if not operators[type(op)](left, right):
                    return False
                left = right
            return True
        elif isinstance(node, ast.BoolOp):
            values = [_evaluate(value) for value in node.values]
            return operators[type(node.op)](*values)
        else:
            raise ValueError(f"Unsupported node type: {type(node)}")

    return _evaluate(tree)
