import heapq

def cheapest_route(edges: list[tuple[str, str, int]], start: str, goal: str) -> tuple[int, list[str]] | None:
    graph = {}
    for u, v, w in edges:
        if u not in graph: graph[u] = {}
        if v not in graph: graph[v] = {}
        graph[u][v] = graph[v][u] = w

    shortest_distances = {node: float('inf') for node in graph}
    shortest_distances[start] = 0
    previous_nodes = {node: None for node in graph}

    queue = [(0, start)]
    while queue:
        dist, node = heapq.heappop(queue)
        if dist != shortest_distances[node]:
            continue
        for neighbor, weight in graph[node].items():
            old_dist = shortest_distances[neighbor]
            new_dist = dist + weight
            if new_dist < old_dist:
                shortest_distances[neighbor] = new_dist
                previous_nodes[neighbor] = node
                heapq.heappush(queue, (new_dist, neighbor))

    if shortest_distances[goal] == float('inf'):
        return None

    path = []
    while goal is not None:
        path.append(goal)
        goal = previous_nodes[goal]
    path.reverse()

    return (shortest_distances[path[-1]], path)
```

This function first constructs the graph from the edges, then uses Dijkstra's algorithm to find the shortest path from the start node to the goal node. The algorithm uses a priority queue to always process the node with the smallest distance first. If a shorter path to a node is found, it is updated and its new distance is pushed into the queue. The function finally constructs the path from the start node to the goal node by following the previous nodes.

