import re

def tokenize_code(source: str) -> list[tuple[str, str]]:
    tokens = []
    token_specification = [
        ("NUMBER",   r"\d+(\.\d*)?"),
        ("NAME",     r"[_a-zA-Z][_a-zA-Z0-9]*"),
        ("OP",       r"[+\-*/<>=(),.]"),
        ("SKIP",     r"\s+"),
    ]
    tok_regex = '|'.join('(?P<%s>%s)' % pair for pair in token_specification)
    for mo in re.finditer(tok_regex, source):
        kind = mo.lastgroup
        if kind == "SKIP":
            continue
        elif kind == "NUMBER" or kind == "NAME":
            text = mo.group(kind)
            if kind == "NUMBER" and "." in text and text.count(".") > 1:
                raise ValueError("Invalid number: " + text)
            tokens.append((kind, text))
        elif kind == "OP":
            text = mo.group(kind)
            if len(text) > 2:
                tokens.append(("OP", text[:2]))
                tokens.append(("OP", text[2:]))
            else:
                tokens.append((kind, text))
    return tokens
