def rotate_rings(matrix: list[list[int]], k: int) -> list[list[int]]:
    if not matrix:
        return []

    n = len(matrix)
    new_matrix = [[0]*n for _ in range(n)]

    for i in range(n//2):
        for j in range(i, n-i-1):
            ring_start_i, ring_start_j = i, j
            ring_end_i, ring_end_j = n-i-1, n-j-1

            # Save the first element of the ring
            temp = matrix[ring_start_i][ring_start_j]

            # Rotate the ring clockwise by k positions
            for _ in range(k):
                # Move the top row
                for x in range(ring_start_j, ring_end_j):
                    matrix[ring_start_i][x] = matrix[ring_start_i][x+1]
                # Move the right column
                for x in range(ring_start_i, ring_end_i):
                    matrix[x][ring_end_j] = matrix[x+1][ring_end_j]
                # Move the bottom row
                for x in range(ring_end_j, ring_start_j, -1):
                    matrix[ring_end_i][x] = matrix[ring_end_i][x-1]
                # Move the left column
                for x in range(ring_end_i, ring_start_i, -1):
                    matrix[x][ring_start_j] = matrix[x-1][ring_start_j]
                # Restore the first element of the ring
                matrix[ring_start_i+1][ring_start_j] = temp

    # If n is odd, copy the center element to the new matrix
    if n % 2 != 0:
        new_matrix[n//2][n//2] = matrix[n//2][n//2]

    return matrix
