def simulate_lru(capacity: int, operations: list[tuple]) -> tuple[list, list]:
    if capacity == 0:
        return [], []

    cache = {}
    keys = []
    results = []

    for operation in operations:
        if operation[0] == "put":
            key, value = operation[1], operation[2]
            if key in cache:
                keys.remove(key)
            elif len(cache) == capacity:
                del cache[keys.pop(0)]
            cache[key] = value
            keys.append(key)
        elif operation[0] == "get":
            key = operation[1]
            if key in cache:
                results.append(cache[key])
                keys.remove(key)
                keys.append(key)
            else:
                results.append(None)

    return results, keys
