def run_stack_machine(program: list[str]) -> list[int]:
    stack = []
    ip = 0  # instruction pointer
    max_instructions = 1000
    while ip < len(program) and ip < max_instructions:
        instruction = program[ip].split()
        op = instruction[0]
        if op == 'PUSH':
            stack.append(int(instruction[1]))
        elif op == 'POP':
            if not stack:
                raise ValueError('Not enough values on stack')
            stack.pop()
        elif op == 'DUP':
            if len(stack) < 1:
                raise ValueError('Not enough values on stack')
            stack.append(stack[-1])
        elif op == 'SWAP':
            if len(stack) < 2:
                raise ValueError('Not enough values on stack')
            stack[-1], stack[-2] = stack[-2], stack[-1]
        elif op == 'ADD':
            if len(stack) < 2:
                raise ValueError('Not enough values on stack')
            stack.append(stack.pop() + stack.pop())
        elif op == 'SUB':
            if len(stack) < 2:
                raise ValueError('Not enough values on stack')
            a = stack.pop()
            b = stack.pop()
            stack.append(b - a)
        elif op == 'MUL':
            if len(stack) < 2:
                raise ValueError('Not enough values on stack')
            stack.append(stack.pop() * stack.pop())
        elif op == 'JMP':
            ip = int(instruction[1])
            continue
        elif op == 'JZ':
            if not stack:
                raise ValueError('Not enough values on stack')
            if stack[-1] == 0:
                ip = int(instruction[1])
                stack.pop()
                continue
        elif op == 'HALT':
            break
        else:
            raise ValueError('Unknown instruction')
        ip += 1
    if ip == max_instructions:
        raise RuntimeError('Too many instructions executed')
    return stack
```

