def process_orders(events: list[tuple[str, str, int]]) -> tuple[dict[str, int], list[tuple[str, int]]]:
    stock = {}
    waiting = {}
    order_queue = {}
    for event in events:
        kind, item, quantity = event
        if kind == 'receive':
            if item in stock:
                stock[item] += quantity
            else:
                stock[item] = quantity
            while item in order_queue and order_queue[item] > 0 and stock[item] > 0:
                order_quantity = min(order_queue[item], stock[item])
                stock[item] -= order_quantity
                order_queue[item] -= order_quantity
        elif kind == 'order':
            if item in order_queue:
                order_queue[item] += quantity
            else:
                order_queue[item] = quantity
            while item in stock and stock[item] > 0 and order_queue[item] > 0:
                order_quantity = min(order_queue[item], stock[item])
                stock[item] -= order_quantity
                order_queue[item] -= order_quantity
    waiting_list = [(item, quantity) for item, quantity in order_queue.items() if quantity > 0]
    return (stock, waiting_list)
