def run_bank_ops(balances: dict[str, int], ops: list[tuple]) -> tuple[dict[str, int], list[int]]:
    failed = []
    final_balances = balances.copy()
    fee = 2

    for i, op in enumerate(ops):
        op_type, account, *args = op

        if account not in final_balances or (op_type in ('deposit', 'withdraw', 'transfer') and int(args[0]) <= 0) or (op_type == 'freeze' or op_type == 'unfreeze' and account in final_balances['frozen']):
            failed.append(i)
            continue

        if op_type == 'deposit':
            final_balances[account] += int(args[0])
        elif op_type == 'withdraw':
            if final_balances[account] - int(args[0]) < 0:
                failed.append(i)
                continue
            final_balances[account] -= int(args[0])
        elif op_type == 'transfer':
            target = args[0]
            amount = int(args[1])
            if target == account or final_balances[account] - amount - fee < 0 or target not in final_balances:
                failed.append(i)
                continue
            final_balances[account] -= amount + fee
            final_balances[target] += amount
        elif op_type == 'freeze':
            if 'frozen' not in final_balances:
                final_balances['frozen'] = []
            final_balances['frozen'].append(account)
            final_balances[account] = 0
        elif op_type == 'unfreeze':
            if account not in final_balances['frozen']:
                failed.append(i)
                continue
            final_balances['frozen'].remove(account)
            final_balances[account] = 0
        else:
            failed.append(i)

    return final_balances, failed
