def min_max_normalize(nums: list[float]) -> list[float]:
    if not nums:
        return []
    min_num = min(nums)
    max_num = max(nums)
    if min_num == max_num:
        return [0.0] * len(nums)
    return [round((num - min_num) / (max_num - min_num), 2) for num in nums]
