    length = len(numbers)
    mean = round(sum(numbers) / length, 2)
    if length % 2 == 0:
        median = round((numbers[length // 2 - 1] + numbers[length // 2]) / 2, 2)
    else:
        median = round(numbers[length // 2], 2)
    return (mean, median)
