def min_coins_bounded(coins: list[int], limits: list[int], target: int) -> int:
    dp = [0] + [-1]*target
    for i in range(len(coins)):
        for j in range(coins[i], target+1):
            if dp[j-coins[i]] != -1 and dp[j-coins[i]]+1 < limits[i]:
                if dp[j] == -1 or dp[j-coins[i]]+1 < dp[j]:
                    dp[j] = dp[j-coins[i]]+1
    return dp[-1]
```

