def caesar_cipher(text: str, shift: int) -> str:
    ciphered_text = ""
    for char in text:
        if char.isalpha():
            ascii_offset = ord('a') if char.islower() else ord('A')
            ciphered_char = chr((ord(char) - ascii_offset + shift) % 26 + ascii_offset)
            ciphered_text += ciphered_char
        else:
            ciphered_text += char
    return ciphered_text
