def identifier_to_snake(name: str) -> str:
    if not name:
        return ""

    words = []
    word = ""
    for char in name:
        if char.isalnum():
            word += char
        elif char in ['-', '_']:
            if word:
                words.append(word)
                word = ""
        else:
            return ""
    if word:
        words.append(word)

    return "_".join(words).lower()
