def solve_congruences(congruences: list[tuple[int, int]]) -> tuple[int, int] | None:
    if not congruences:
        return (0, 1)

    def gcd(a, b):
        while b:
            a, b = b, a % b
        return a

    def lcm(a, b):
        return a * b // gcd(a, b)

    r, m = congruences[0]
    for r, m in congruences[1:]:
        r %= m
        if r < 0:
            r += m
        g = gcd(m, r)
        if g > 1:
            m //= g
            r //= g
        r %= m
        if r < 0:
            r += m
        if m % r:
            return None
        r *= pow(m, -1, r)
        m = lcm(m, r)

    return (r * m % m, m)
```

