def simulate_lru(capacity: int, operations: list[tuple]) -> tuple[list, list]:
    if capacity == 0:
        return ([], [])

    cache = {}
    keys = []
    results = []

    for op in operations:
        if op[0] == "put":
            if len(cache) == capacity and op[1] not in cache:
                del cache[keys.pop(0)]
            cache[op[1]] = op[2]
            keys.append(op[1])
        elif op[0] == "get":
            if op[1] in cache:
                results.append(cache[op[1]])
                keys.remove(op[1])
                keys.append(op[1])
            else:
                results.append(None)

    return (results, keys)
