def solve_congruences(congruences: list[tuple[int, int]]) -> tuple[int, int] | None:
    if not congruences:
        return (0, 1)

    def gcd(a, b):
        while b:
            a, b = b, a % b
        return a

    def lcm(a, b):
        return a * b // gcd(a, b)

    x, m = 0, 1
    for r, mod in congruences:
        while x % mod != r % mod:
            x += m
        m = lcm(m, mod)

    return (x % m, m)
```

