def stabilize_sandpile(grid: list[list[int]]) -> list[list[int]]:
    rows = len(grid)
    cols = len(grid[0])
    stable_grid = [[grid[i][j] for j in range(cols)] for i in range(rows)]

    while True:
        overflow = False
        for i in range(rows):
            for j in range(cols):
                if stable_grid[i][j] >= 4:
                    overflow = True
                    stable_grid[i][j] -= 4
                    if i > 0:
                        stable_grid[i-1][j] += 1
                    if i < rows - 1:
                        stable_grid[i+1][j] += 1
                    if j > 0:
                        stable_grid[i][j-1] += 1
                    if j < cols - 1:
                        stable_grid[i][j+1] += 1

        if not overflow:
            break

        for i in range(rows):
            for j in range(cols):
                if stable_grid[i][j] > 3:
                    stable_grid[i][j] = 3

    return stable_grid
```

