from collections import deque

def shortest_path_one_break(grid: list[str]) -> int:
    rows, cols = len(grid), len(grid[0])
    start, end = None, None
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 'S':
                start = (r, c, 0)  # (row, col, wall breaks)
            elif grid[r][c] == 'E':
                end = (r, c)
    if start is None or end is None:
        return -1

    queue = deque([start])
    visited = {start[0:2]: 0}
    while queue:
        r, c, b = queue.popleft()
        if (r, c) == end:
            return b
        for nr, nc in ((r-1, c), (r+1, c), (r, c-1), (r, c+1)):
            if 0 <= nr < rows and 0 <= nc < cols:
                nb = b
                if grid[nr][nc] == '#':
                    nb += 1
                if nb < 2 and (nr, nc) not in visited or nb < visited.get((nr, nc), 2):
                    visited[(nr, nc)] = nb
                    queue.append((nr, nc, nb))
    return -1
