```python
from collections import deque

def shortest_path_one_break(grid: list[str]) -> int:
    rows, cols = len(grid), len(grid[0])
    start, end = None, None
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 'S':
                start = (i, j, 0)
            elif grid[i][j] == 'E':
                end = (i, j)
    if start is None or end is None:
        return -1

    queue = deque([start])
    visited = {start[0:2]: 0}
    while queue:
        x, y, breaks = queue.popleft()
        if (x, y) == end:
            return breaks
        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nx, ny = x + dx, y + dy
            if 0 <= nx < rows and 0 <= ny < cols:
                if grid[nx][ny] == '#':
                    if breaks + 1 < visited.get((nx, ny), float('inf')):
                        visited[nx, ny] = breaks + 1
                        queue.append((nx, ny, breaks + 1))
                else:
                    if breaks < visited.get((nx, ny), float('inf')):
                        visited[nx, ny] = breaks
                        queue.appendleft((nx, ny, breaks))
