import re

def tokenize_code(source: str) -> list[tuple[str, str]]:
    tokens = []
    source = source.strip()
    while source:
        if source[0].isalpha() or source[0] == '_':
            match = re.match(r'[a-zA-Z_]\w*', source)
            tokens.append(('NAME', match.group()))
            source = source[match.end():]
        elif source[0].isdigit():
            match = re.match(r'\d*\.\d+|\d+', source)
            tokens.append(('NUMBER', match.group()))
            source = source[match.end():]
        elif source[0] in '+-*/<>=(),':
            tokens.append(('OP', source[0]))
            source = source[1:]
        elif source[0] == '=':
            if len(source) > 1 and source[1] == '=':
                tokens.append(('OP', '=='))
                source = source[2:]
            else:
                tokens.append(('OP', '='))
                source = source[1:]
        elif source[0] in ' \t\n':
            source = source[1:]
        else:
            raise ValueError('Invalid character')
    return tokens
```

