def teller_waits(arrivals: list[int], service_times: list[int], tellers: int) -> list[int]:
    if not arrivals or not service_times or not tellers:
        return []

    wait_times = [0] * len(arrivals)
    free_times = [0] * tellers

    for i in range(len(arrivals)):
        earliest_free_time = min(free_times)
        if arrivals[i] >= earliest_free_time:
            wait_times[i] = arrivals[i] - earliest_free_time
            free_times[free_times.index(earliest_free_time)] = arrivals[i] + service_times[i]
        else:
            wait_times[i] = 0

    return wait_times

