        if (x, y) in blocked:
            return False
        # Check if there is a queen in the same row or column
        for i in range(n):
            if (x, i) in blocked or (i, y) in blocked:
                return False
        # Check if there is a queen in the diagonal
        for i, j in blocked:
            if abs(x - i) == abs(y - j):
                return False
        return True

