def format_table(rows: list[list[str]], aligns: str) -> str:
    if not rows:
        return ""

    # Determine the width of each column
    widths = [max(len(row[i]) for row in rows) for i in range(len(rows[0]))]

    # Determine the alignment for each column
    alignments = [align for align in aligns]

    # Format the table
    table = ""
    for i, row in enumerate(rows):
        for j, cell in enumerate(row):
            if alignments[j] == "l":
                table += cell.ljust(widths[j]) + " | "
            elif alignments[j] == "r":
                table += cell.rjust(widths[j]) + " | "
            elif alignments[j] == "c":
                table += cell.center(widths[j]) + " | "
        table = table[:-3]  # Remove the last " | "
        table += "\n"
    return table

