def convert_base(number: str, from_base: int, to_base: int) -> str:
    if not number:
        raise ValueError("Number cannot be empty")
    if not (2 <= from_base <= 36 and 2 <= to_base <= 36):
        raise ValueError("Base must be between 2 and 36")
    if from_base == 10:
        number = int(number)
    else:
        number = int(number, from_base)
    if number == 0:
        return '0'
    if number < 0:
        return '-' + convert_base(-number, to_base, to_base)
    digits = '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ'[:to_base]
    result = ''
    while number:
        number, digit = divmod(number, to_base)
        result = digits[digit] + result
    return result.lower()
