def identifier_to_snake(name: str) -> str:
    if not name.isascii():
        raise ValueError("Name should be ASCII")
    if not all(c.isalnum() or c in ['_', '-'] for c in name):
        raise ValueError("Name should only contain alphanumeric characters, underscores and hyphens")
    if not any(c.isalpha() for c in name):
        raise ValueError("Name should contain at least one alphabetic character")

    new_name = []
    for i, c in enumerate(name):
        if c.isupper() and i > 0 and name[i-1].islower():
            new_name.append('_')
        new_name.append(c.lower())

    return ''.join(new_name)
```

