    if not matrix or len(matrix) == 0:
        return []

    n = len(matrix)
    m = n // 2
    k = k % (2 * n - 4) if n > 1 else 0

    for i in range(m):
        ring_len = 2 * (n - 2 * i) - 4
        rotate_count = k if ring_len <= 0 else k % ring_len

        for _ in range(rotate_count):
