def format_table(rows: list[list[str]], aligns: str) -> str:
    if not rows:
        return ""

    # Calculate the width of each column
    widths = [max(len(row[col]) for row in rows) for col in range(len(rows[0]))]

    # Create the formatted table
    table = []
    for row in rows:
        formatted_row = []
        for i, cell in enumerate(row):
            align = aligns[i] if i < len(aligns) else aligns[-1]
            if align == 'l':
                formatted_row.append(cell.ljust(widths[i]))
            elif align == 'r':
                formatted_row.append(cell.rjust(widths[i]))
            elif align == 'c':
                formatted_row.append(cell.center(widths[i]))
        table.append(" | ".join(formatted_row))

    return "\n".join(table)
```

