            if in_placeholder:
                placeholder += char
                in_placeholder = False
                if placeholder[1:-1] in values:
                    result += values[placeholder[1:-1]]
                else:
                    result += placeholder
                placeholder = ""
            else:
                result += char
        else:
            if in_placeholder:
                placeholder += char
            else:
                result += char

    return result
