            if item in stock:
                stock[item] += quantity
            else:
                stock[item] = quantity
        elif kind == 'order':
            if item in stock and stock[item] >= quantity:
                stock[item] -= quantity
                if stock[item] == 0:
                    del stock[item]
            else:
                waiting.append(event)
    return stock, waiting
