from collections import deque

def min_slides(grid: list[str]) -> int:
    rows, cols = len(grid), len(grid[0])
    start, end = None, None
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 'S':
                start = (i, j)
            elif grid[i][j] == 'E':
                end = (i, j)
    if start is None or end is None:
        return -1

    queue = deque([(*start, 0)])
    visited = {start}
    while queue:
        x, y, steps = queue.popleft()
        if (x, y) == end:
            return steps
        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nx, ny = x + dx, y + dy
            if 0 <= nx < rows and 0 <= ny < cols and grid[nx][ny] != '#' and (nx, ny) not in visited:
                queue.append((nx, ny, steps + 1))
                visited.add((nx, ny))
    return -1
```

This function first finds the start and end cells in the grid. If either of them is not found, it returns -1. Then it initializes a BFS queue with the start cell and the number of steps as 0. It continues to dequeue cells from the queue, checking each cell's neighbors in the four directions. If a neighbor is not a wall and has not been visited before, it is added to the queue with the number of steps incremented by 1. The function returns the number of steps when the end cell is found. If the end cell cannot be reached, it returns -1.

