    while i < len(template):
        if template[i] == "{":
            if i + 1 < len(template) and template[i+1] == "{":
                result += "{"
                i += 2
            else:
                brace_start = i
                brace_end = template.find("}", brace_start + 1)
                if brace_end == -1:
