def rotate_elements(matrix: list[list[int]], k: int) -> list[list[int]]:
    n = len(matrix)
    m = len(matrix[0])
    new_matrix = [[0]*m for _ in range(n)]

    for i in range(n):
        for j in range(m):
            new_i = (i + k / m) % n
            new_j = (j + k / n) % m
            new_matrix[int(new_i)][int(new_j)] = matrix[i][j]

    return new_matrix

