            if item in stock:
                stock[item] += quantity
            else:
                stock[item] = quantity
        elif kind == 'order':
            while quantity > 0 and waiting and waiting[0][0] == item:
                waiting_quantity = waiting[0][1]
                if quantity >= waiting_quantity:
                    quantity -= waiting_quantity
                    waiting.pop(0)
