def run_stack_machine(program: list[str]) -> list[int]:
    stack = []
    pointer = 0
    max_instructions = 1000
    while pointer < len(program) and pointer < max_instructions:
        instruction = program[pointer].split()
        opcode = instruction[0]
        if opcode == 'PUSH':
            stack.append(int(instruction[1]))
        elif opcode == 'POP':
            if not stack:
                raise ValueError('No values on stack')
            stack.pop()
        elif opcode == 'DUP':
            if not stack:
                raise ValueError('No values on stack')
            stack.append(stack[-1])
        elif opcode == 'SWAP':
            if len(stack) < 2:
                raise ValueError('Not enough values on stack')
            stack[-1], stack[-2] = stack[-2], stack[-1]
        elif opcode == 'ADD':
            if len(stack) < 2:
                raise ValueError('Not enough values on stack')
            stack.append(stack.pop() + stack.pop())
        elif opcode == 'SUB':
            if len(stack) < 2:
                raise ValueError('Not enough values on stack')
            a = stack.pop()
            b = stack.pop()
            stack.append(b - a)
        elif opcode == 'MUL':
            if len(stack) < 2:
                raise ValueError('Not enough values on stack')
            stack.append(stack.pop() * stack.pop())
        elif opcode == 'JMP':
            pointer = int(instruction[1])
            continue
        elif opcode == 'JZ':
            if not stack:
                raise ValueError('No values on stack')
            if stack[-1] == 0:
                pointer = int(instruction[1])
                continue
        elif opcode == 'HALT':
            break
        else:
            raise ValueError('Invalid opcode')
        pointer += 1
    if pointer == max_instructions:
        raise RuntimeError('Maximum instructions exceeded')
    return stack
