            team_dict[home]['goals_scored'] += home_goals
            team_dict[away]['goal_difference'] -= away_goals - home_goals
            team_dict[away]['goals_scored'] += away_goals
        elif home_goals < away_goals:
            team_dict[away]['points'] += 3
            team_dict[away]['goal_difference'] += away_goals - home_goals
