def run_stack_machine(program: list[str]) -> list[int]:
    stack = []
    ip = 0
    max_instructions = 1000
    num_instructions = 0

    while ip < len(program) and num_instructions < max_instructions:
        instruction = program[ip].split()
        op = instruction[0]

        if op == 'PUSH':
            if len(instruction) != 2 or not instruction[1].isdigit():
                raise ValueError('Invalid PUSH instruction')
            stack.append(int(instruction[1]))

        elif op == 'POP':
            if not stack:
                raise ValueError('Empty stack')
            stack.pop()

        elif op == 'DUP':
            if not stack:
                raise ValueError('Empty stack')
            stack.append(stack[-1])

        elif op == 'SWAP':
            if len(stack) < 2:
                raise ValueError('Not enough elements in stack')
            stack[-1], stack[-2] = stack[-2], stack[-1]

        elif op == 'ADD':
            if len(stack) < 2:
                raise ValueError('Not enough elements in stack')
            a = stack.pop()
            b = stack.pop()
            stack.append(a + b)

        elif op == 'SUB':
            if len(stack) < 2:
                raise ValueError('Not enough elements in stack')
            a = stack.pop()
            b = stack.pop()
            stack.append(a - b)

        elif op == 'MUL':
            if len(stack) < 2:
                raise ValueError('Not enough elements in stack')
            a = stack.pop()
            b = stack.pop()
            stack.append(a * b)

        elif op == 'JMP':
            if len(instruction) != 2 or not instruction[1].isdigit() or int(instruction[1]) >= len(program):
                raise ValueError('Invalid JMP instruction')
            ip = int(instruction[1])
            continue

        elif op == 'JZ':
            if len(instruction) != 2 or not instruction[1].isdigit() or int(instruction[1]) >= len(program):
                raise ValueError('Invalid JZ instruction')
            if not stack:
                raise ValueError('Empty stack')
            if stack[-1] == 0:
                ip = int(instruction[1])
                continue

        elif op == 'HALT':
            break

        else:
            raise ValueError('Invalid instruction')

        ip += 1
        num_instructions += 1

    if num_instructions == max_instructions:
        raise RuntimeError('Maximum number of instructions executed')

    return stack
```

